\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 (ff. 155\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 156\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f2\lang1032\fs24\chcbpat17 O<\u7985 ? \u948 \'e4\u8050 ? \u947 \'e3\u949 \'e5\u957 \'ed\u8057 ?\u956 \'ec\u949 \'e5\u957 \'ed\u959 \'ef\u953 \'e9 \u960 \'f0\u961 \'f1\u959 \'ef\u966 \'f6\u8134 ?\u964 \'f4\u945 \'e1\u953 \'e9 \u7952 ?\u957 \'ed \u964 \'f4\u945 \'e1\u8150 ?\u962 \'f2 \u7969 ?\u956 \'ec\u8051 ?\u961 \'f1\u945 \'e1\u953 \'e9\u962 \'f2}}\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\plain \f1\lang1033\fs24 \u8051 ?\plain \f2\lang1032\fs24 \u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24 \u7984 ?\plain \f2\lang1032\fs24 \u963 \'f3\plain \f1\lang1033\fs24 \u8054 ? \plain \f2\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24 \u8023 ?\plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs24 : \u7952 ?\plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24 \u8054 ? \plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24 \u8050 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u931 \'d3\u945 \'e1\u959 \'ef\plain \f1\lang1033\fs24 \u8058 ?\plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u916 \'c4\u945 \'e1\u946 \'e2\plain \f1\lang1033\fs24 \u8054 ?\plain \f2\lang1032\fs24 \u948 \'e4\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u931 \'d3\u945 \'e1\u956 \'ec\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24 \u8052 ?\plain \f2\lang1032\fs24 \u955 \'eb\plain \f1\lang1033\fs24  ... \plain \f2\lang1032\fs24 \u916 \'c4\u945 \'e1\u957 \'ed\u953 \'e9\plain \f1\lang1033\fs