\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (ff.\~158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 159\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liste der Patriarchen}}\plain \f1\lang1033\fs24  von Konstantinopel bis zu Patriarch Joseph (1416\endash 1439), vgl. sehr \u228 \'e4hnliche Listen bei \plain \f1\scaps\lang1033\fs24 C. de Boor\plain \f1\lang1033\fs24 , Nicephori archiepiscopi Constantinopolitani opuscula historica, Leipzig 1880, S. 112\endash 121 (dort nur bis Photios, Stephanos): \plain \f2\lang1032\fs24 \u928 \'d0\u945 \'e1\u964 \'f4\u961 \'f1\u953 \'e9\plain \f1\lang1033\fs24 \u8049 ?\plain \f2\lang1032\fs24 \u961 \'f1\u967 \'f7\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u922 \'ca\u969 \'f9\u957 \'ed\u963 \'f3\u964 \'f4\u945 \'e1\u957 \'ed\u964 \'f4\u953 \'e9\u957 \'ed\u959 \'ef\u965 \'f5\u960 \'f0\plain \f1\lang1033\fs24 \u8057 ?\plain \f2\lang1032\fs24 \u955 \'eb\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\lang1032\fs24\chcbpat17 \u931 \'d3\u964 \'f4\u8049 ?\u967 \'f7\u953 \'e9\u962 \'f2 \u7952 ?\u954 \'ea \u964 \'f4\u8182 ?\u957 \'ed \u959 \'ef\u884 ?}}\plain \f1\lang1033\fs24 , in margine: \u8003 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \u7952 ?\plain \f2\lang1032\fs24 \u967 \'f7\u949 \'e5\u953 \'e9\u961 \'f1\u959 \'ef\u964 \'f4\plain \f1\lang1033\fs24 \u8057 ?\plain \f2\lang1032\fs24 \u957 \'ed\u951 \'e7\u963 \'f3\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \u7944 ?\plain \f2\lang1032\fs24 \u957 \'ed\u948 \'e4\u961 \'f1\plain \f1\lang1033\fs24 \u8051 ?\plain \f2\lang1032\fs24 \u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \u8001 ? \u7936 ?\plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24 \u8057 ?\plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u959 \'ef\u955 \'eb\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24 \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u920 \'c8\u961 \'f1\plain \f1\lang1033\fs24 \u8049 ?\plain \f2\lang1032\fs24 \u954 \'ea\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  \u7952 ?\plain \f2\lang1032\fs24 \u960 \'f0\plain \f1\lang1033\fs24 \u8055 ?\plain \f2\lang1032\fs24 \u963 \'f3\u954 \'ea\u959 \'ef\u960 \'f0\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24 . ... \plain \f2\lang1032\fs24 \u961 \'f1\u956 \'ec\u951 \'e7\u884 ?\plain \f1\lang1033\fs24  >\plain \f2\lang1032\fs24 \u917 \'c5<\plain \f1\lang1033\fs24 \u8016 ?\plain \f2\lang1032\fs24 \u952 \'e8\plain \f1\lang1033\fs24 \u8059 ?\plain \f2\lang1032\fs24 \u956 \'ec\u953 \'e9\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u884 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\plain \f1\lang1033\fs24 \u8134 ?\plain \f2\lang1032\fs24 \u957 \'ed\u949 \'e5\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24 .; \plain \f2\lang1032\fs24 \u961 \'f1\u956 \'ec\u952 \'e8\u884 ?\plain \f1\lang1033\fs24  \u7992 ?\plain \f2\lang1032\fs24 \u969 \'f9\u963 \'f3\plain \f1\lang1033\fs24 \u8053 ?\plain \f2\lang1032\fs24 \u966 \'f6\plain \f1\lang1033\fs24 .}

