\par \pard\fi0\li0\ql\ri0\sb0\sa195\itap0 (ff. 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lib. I: \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  (I, 262) \plain \f2\lang1032\fs24 \u947 \'e3\u965 \'f5\u957 \'ed\u945 \'e1\u953 \'e9\u954 \'ea\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u945 \'e1\u957 \'ed\u964 \'f4\u953 \'e9\u946 \'e2\u959 \'ef\u955 \'eb\u959 \'ef\u8166 ?\u963 \'f3\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u8052 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u959 \'ef\u970 \'fa\u941 \'dd\u957 \'ed\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \u8230 \'85 \emdash  (ff. 64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Lib. II: \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\u8054 ? \u7937 ?\u955 \'eb\u8061 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2 \u946 \'e2\u884 ?\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f2\lang1032\fs24\chcbpat17 \u7944 ?\u961 \'f1\u967 \'f7\u949 \'e5\u955 \'eb\u940 \'dc\u8179 ? \u948 \'e4\u8050 ? \u957 \'ed\u941 \'dd\u969 \'f9\u957 \'ed \u7974 ?\u961 \'f1\u958 \'ee\u949 \'e5 \u952 \'e8\u959 \'ef\u961 \'f1\u973 \'fd\u946 \'e2\u969 \'f9\u957 \'ed}}\plain \f1\lang1033\fs24  \u7969 ? \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8172 ?\u974 \'fe\u956 \'ec\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u959 \'ef\u948 \'e4\u951 \'e7\u956 \'ec\u943 \'df\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u940 \'dc\u947 \'e3\u954 \'ea\u951 \'e7\plain \f1\lang1033\fs24  ... . \emdash  (ff. 116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lib. III: \plain \f2\lang1032\fs24 \u934 \'d6\u955 \'eb\u945 \'e1\u965 \'f5\u8147 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7992 ?\u969 \'f9\u963 \'f3\u8053 ?\u960 \'f0\u959 \'ef\u965 \'f5 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ? \u7937 ?\u955 \'eb\u8061 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2 \u947 \'e3\u884 ?\plain \f1\lang1033\fs24  (\plain \f2\lang1032\fs24 \u947 \'e3\plain \f1\lang1033\fs24 \u884 ? corr. post ras.). \emdash  Auf f. 144\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  muss die Vorlage eine L\u252 \'fccke gehabt haben, denn der Schreiber l\u228 \'e4sst Platz frei. Schreiber F (?) schreibt den Nachtrag in die L\u252 \'fccke (III, 482\endash 488) sowie in margine (III, 488\endash 508) und endet auf f. 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  mit dem Hinweis: \plain \f2\lang1032\fs24 \u8017 ?\u960 \'f0\u8057 ?\u963 \'f3\u964 \'f4\u961 \'f1\u949 \'e5\u968 \'f8\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u8020 ?\u952 \'e8\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u951 \'e7\u7991 ?\u960 \'f0\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7988 ?\u948 \'e4\u959 \'ef\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u8134 ?\u956 \'ec\u945 \'e1\plain \f1\lang1033\fs24 . \emdash  (ff. 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 184\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lib. IV:\plain \f2\lang1032\fs24  \u7992 ?\u969 \'f9\u963 \'f3\u8053 ?\u960 \'f0\u959 \'ef\u965 \'f5 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ? \u7937 ?\u955 \'eb\u8061 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2 \u948 \'e4\u884 ?\plain \f1\lang1033\fs24 . \emdash  (ff. 184\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lib. V, vgl. auch die Kollation bei \plain \f1\scaps\lang1033\fs24 Westermann 1866\plain \f1\lang1033\fs24 , S. 8\endash 16: \plain \f2\lang1032\fs24 \u934 \'d6\u955 \'eb\u945 \'e1\u965 \'f5\u8147 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7992 ?\u969 \'f9\u963 \'f3\u8053 ?\u960 \'f0\u959 \'ef\u965 \'f5 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ? \u7937 ?\u955 \'eb\u8061 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2 \u948 \'e4\plain \f1\lang1033\fs24 \u884 ? (auf dem rechten Rand), \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u884 ?\plain \f1\lang1033\fs24  (auf dem linken Rand). \emdash  (ff. 219\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 244\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lib. VI: \plain \f2\lang1032\fs24 \u934 \'d6\u955 \'eb\u945 \'e1\u965 \'f5\u8147 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7992 ?\u969 \'f9\u963 \'f3\u8053 ?\u960 \'f0\u959 \'ef\u965 \'f5 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ? \u7937 ?\u955 \'eb\u8061 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2 \u963 \'f3\u964 \'f4\plain \f1\lang1033\fs24 \u884 ? (auf dem rechten Rand), \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u884 ?\plain \f1\lang1033\fs24  (auf dem linken Rand). \emdash  (ff. 244\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 270\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Lib. VII: \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\u8054 ? \u7937 ?\u955 \'eb\u8061 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7992 ?\u969 \'f9\u963 \'f3\u8053 ?\u960 \'f0\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2 \u950 \'e6\u884 ? \plain \f1\lang1033\fs24 (auf dem rechten Rand), \plain \f1\i\lang1033\fs24 des.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8005 ?\u964 \'f4\u953 \'e9 \u956 \'ec\u972 \'fc\u957 \'ed\u951 \'e7\u962 \'f2 \u964 \'f4\u945 \'e1\u973 \'fd\u964 \'f4\u951 \'e7\u962 \'f2 \u960 \'f0\u945 \'e1\u961 \'f1\u8048 ? \u960 \'f0\u8118 ?\u963 \'f3\u945 \'e1\u957 \'ed \u964 \'f4\u8052 ?\u957 \'ed \u7936 ?\u957 \'ed\u945 \'e1\u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u8052 ?\u957 \'ed \u7952 ?\u963 \'f3\u964 \'f4\u959 \'ef\u967 \'f7\u945 \'e1\u963 \'f3\u940 \'dc\u956 \'ec\u951 \'e7\u957 \'ed. \plain \f1\lang1033\fs24 Darunter: \plain \f2\lang1032\fs24 \u934 \'d6\u955 \'eb\u945 \'e1\u965 \'f5\u8147 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7992 ?\u969 \'f9\u963 \'f3\u8053 ?\u960 \'f0\u959 \'ef\u965 \'f5 \u7993 ?\u959 \'ef\u965 \'f5\u948 \'e4\u945 \'e1\u970 \'fa\u954 \'ea\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7985 ?\u963 \'f3\u964 \'f4\u959 \'ef\u961 \'f1\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ? \u7937 ?\u955 \'eb\u8061 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7957 ?\u946 \'e2\u948 \'e4\u959 \'ef\u956 \'ec\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24 .}

