\par \pard\sl360\slmult1\fi-420\li420\tx420\qj\ri0\sb195\sa0\itap0 Literatur zur Vorlage: James, Catalogue, pl. IX. \emdash  Wilson, N., 'On the transmission of the Greek Lexica'Greek, Roman and Byzantine Studies 23 (1982), 369-75. \emdash  Kyriakou Tsantsanoglou, \plain \f4\lang1032\fs20 \u932 \'d4\u959 \'ef\plain \f1\lang1033\fs20  \plain \f4\lang1032\fs20 \u955 \'eb\u949 \'e5\u958 \'ee\u953 \'e9\u954 \'ea\u959 \'ef\plain \f1\lang1033\fs20  \plain \f4\lang1032\fs20 \u964 \'f4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20  \plain \f4\lang1032\fs20 \u934 \'d6\u953 \'e9\u959 \'ef\u964 \'f4\u953 \'e9\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20 : \plain \f4\lang1032\fs20 \u967 \'f7\u961 \'f1\u959 \'ef\u957 \'ed\u959 \'ef\u955 \'eb\u959 \'ef\u947 \'e3\u951 \'e7\u963 \'f3\u951 \'e7\plain \f3\lang1033\fs20 -\plain \f4\lang1032\fs20 \u967 \'f7\u949 \'e5\u953 \'e9\u961 \'f1\u959 \'ef\u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u951 \'e7\plain \f1\lang1033\fs20 , \plain \f4\lang1032\fs20 \u960 \'f0\u945 \'e1\u961 \'f1\u945 \'e1\u948 \'e4\u959 \'ef\u963 \'f3\u951 \'e7\plain \f1\lang1033\fs20  (Thessalonike, 1967). \emdash  Jackson, D. F., 'Unidentified Medici-Regii Greek Codices', Scriptorium 54 (2000), 197-208, at 206. \emdash  Mooney, L. R., The Index of Middle English Prose Handlist 11: Manuscripts in the Library of Trinity College, Cambridge (Cambridge, 1995), p. 109. \emdash \plain \f5\fs20  Tsantsangolou, K., To Lexikou Tou Ph\u333 \'f4tiou : Chronolog\u275 \'e7s\u275 \'e7-Cheirograph\u275 \'e7 Parados\u275 \'e7, Hell\u275 \'e7nika. Parart\u275 \'e7ma 17 (Thessalonik\u275 \'e7, 1967). \emdash  Miscellanea Bibliothecae Apostolicae Vaticanae. 15, Studie e Testi 453 (Citt\plain \f1\lang1033\fs20 \u195 \'c3 del Vaticano, 2008).}

