\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u951 \'e7\u955 \'eb\u959 \'ef\u8150 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u7990 ?\u952 \'e8\u949 \'e5\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u959 \'ef\u8021 ?\u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u8048 ?\u961 \'f1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u922 \'ca\u945 \'e1\u955 \'eb\u955 \'eb\u8055 ?\u956 \'ec\u945 \'e1\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u8051 ?\u967 \'f7\u961 \'f1\u951 \'e7\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 des.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7944 ?\u948 \'e4\u953 \'e9\u8049 ?\u954 \'ea\u961 \'f1\u953 \'e9\u964 \'f4\u959 \'ef\u962 \'f2\u903 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u948 \'e4\u953 \'e9\u945 \'e1\u967 \'f7\u8061 ?\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u955 \'eb\u945 \'e1\u956 \'ec\u946 \'e2\u8049 ?\u957 \'ed\u949 \'e5\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8050 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u8052 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u953 \'e9\u957 \'ed\u969 \'f9\u963 \'f3\u954 \'ea\u8057 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8051 ?\u959 \'ef\u957 \'ed\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24 . \u7970 ? \plain \f2\lang1032\fs24 \u7936 ?\u966 \'f6\u961 \'f1\u8057 ?\u957 \'ed\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u966 \'f6\u95