1  \u945 \'e1\plain \f1\lang1033\fs24\cf1 \u7985 ?\plain \f2\lang1032\fs24\cf1 \u961 \'f1\plain \f1\lang1033\fs24\cf1 \u8051 ?\plain \f2\lang1032\fs24\cf1 \u963 \'f3\u949 \'e5\u953 \'e9 \u947 \'e3\plain \f1\lang1033\fs24\cf1 \u8049 ?\plain \f2\lang1032\fs24\cf1 \u956 \'ec\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24\cf1 ... (\plain \f1\i\lang1033\fs24\cf1 fol. 173. A.\plain \f1\lang1033\fs24\cf1 //\plain \f1\i\lang1033\fs24\cf1 bib.med.\plain \f1\lang1033\fs24\cf1 ) \plain \f2\lang1032\fs24\cf1 \u950 \'e6\u969 \'f9\plain \f1\lang1033\fs24\cf1 \u8134 ?\plain \f2\lang1032\fs24\cf1 \u962 \'f2\plain \f1\lang1033\fs24\cf1  \plain \f2\lang1032\fs24\cf1 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24\cf1 \u8058 ?\plain \f2\lang1032\fs24\cf1 \u962 \'f2\plain \f1\lang1033\fs24\cf1  \plain \f2\lang1032\fs24\cf1 \u945 \'e1\plain \f1\lang1033\fs24\cf1 \u8016 ?\plain \f2\lang1032\fs24\cf1 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24\cf1 \u8058 ?\plain \f2\lang1032\fs24\cf1 \u962 \'f2\plain \f1\lang1033\fs24\cf1  \u7952 ?\plain \f2\lang1032\fs24\cf1 \u960 \'f0\u953 \'e9\u956 \'ec\plain \f1\lang1033\fs24\cf1 \u8051 ?\plain \f2\lang1032\fs24\cf1 \u957 \'ed\u959 \'ef\u953 \'e9\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24\cf1  ... \plain \f1\i\lang1033\fs24\cf1 des.\plain \f2\lang1032\fs24\cf1  (B.4.1.24) \u964 \'f4\plain \f1\lang1033\fs24\cf1 \u8056 ?\plain \f2\lang1032\fs24\cf1 \u957 \'ed \plain \f1\lang1033\fs24\cf1 \u7952 ?\plain \f2\lang1032\fs24\cf1 \u957 \'ed \u945 \'e1\plain \f1\lang1033\fs24\cf1 \u7984 ?\plain \f2\lang1032\fs24\cf1 \u963 \'f3\u967 \'f7\plain \f1\lang1033\fs24\cf1 \u8059 ?\plain \f2\lang1032\fs24\cf1 \u957 \'ed\plain \f1\lang1033\fs24\cf1 \u8131 ?\plain \f2\lang1032\fs24\cf1  \u946 \'e2\plain \f1\lang1033\fs24\cf1 \u8055 ?\plain \f2\lang1032\fs24\cf1 \u959 \'ef\u957 \'ed \u964 \'f4\plain \f1\lang1033\fs24\cf1 \u8134 ?\plain \f2\lang1032\fs24\cf1 \u962 \'f2 \plain \f1\lang1033\fs24\cf1 \u8049 ?\plain \f2\lang1032\fs24\cf1 \u947 \'e3\u947 \'e3\u949 \'e5\u955 \'eb\u9