'e7\plain \f1\lang1033\fs24  \u7969 ? \plain \f2\lang1032\fs24 \u967 \'f7\u8061 ?\u961 \'f1\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u949 \'e5\u8150 ?\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u924 \'cc\u949 \'e5\u963 \'f3\u959 \'ef\u960 \'f0\u959 \'ef\u964 \'f4\u945 \'e1\u956 \'ec\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8033 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u964 \'f4\u959 \'ef\u955 \'eb\u8052 ?\u957 \'ed \u960 \'f0\plain \f1\lang1033\fs24 \u8051 ?\plain \f2\lang1032\fs24 \u961 \'f1\u945 \'e1\u957 \'ed \u964 \'f4\u959 \'ef\u8166 ? \u932 \'d4\plain \f1\lang1033\fs24 \u8055 ?\plain \f2\lang1032\fs24 \u947 \'e3\u961 \'f1\u953 \'e9\u948 \'e4\u959 \'ef\u962 \'f2 ... . \emdash  (f.\~1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Treu, \plain \f1\lang1033\fs24 S. 3\endash 4: \plain \f2\lang1032\fs24 \u928 \'d0\u8057 ?\u952 \'e8\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u955 \'eb\u8051 ?\u947 \'e3\u949 \'e5\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u913 \'c1\u8016 ?\u947 \'e3\u959 \'ef\u965 \'f5\u963 \'f3\u964 \'f4\u949 \'e5\u8150 ?\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24 . \emdash  \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u913 \'c1\u8016 ?\u947 \'e3\u959 \'ef\u965 \'f5\u963 \'f3\u964 \'f4\u949 \'e5\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u949 \'e5\u966 \'f6\u8049 ?\u955 \'eb\u945