\pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs24 (p. 43\endash 50) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Listen biblischer Herrscher und r\u246 \'f6mischer Kaiser}}\plain \f1\lang1033\fs24 , vgl.\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 z. B. Chronographia brevis in: \plain \f1\scaps\lang1033\fs24 C. de Boor\plain \f1\lang1033\fs24 , Nicephori archiepiscopi Constantinopolitani opuscula historica, Leipzig 1880, S. 218\endash 223; vgl. {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gennadios Scholarios}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Chrono\-graphia}}\plain \f1\lang1033\fs24 , ed. \plain \f1\scaps\lang1033\fs24 M. Jugie, L. Petit, X. A. Siderides\plain \f1\lang1033\fs24 , Oeuvres compl\u232 \'e8tes de Georges (Gennadios) Scholarios, IV, Paris: 1935, S. 504\endash 511: (pp. 43\endash 44) Von Adam bis Noah: \plain \f2\lang1032\fs24 \u932 \'d4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u952 \'e8\u945 \'e1\u965 \'f5\u956 \'ec\u945 \'e1\u963 \'f3\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u948 \'e4\u961 \'f1\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8000 ?\u957 \'ed\u8057 ?\u956 \'ec\u945 \'e1\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7956 ?\u964 \'f4\u951 \'e7\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7944 ?\u948 \'e4\u8048 ?\u956 \'ec\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7957 ?\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u925 \'cd\u8182 ?\u949 \'e5\plain \f1\lang1033\fs24 . \emdash  (pp. 44\endash 45) Richter: \u7977 ? \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u967 \'f7\u8052 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u961 \'f1\u953 \'e9\u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u924 \'cc\u969 \'f9\u965 \'f5\u963 \'f3\u8051 ?\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7957 ?\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u931 \'d3\u945 \'e1\u956 \'ec\u959 \'ef\u965 \'f5\u8053 ?\u955 \'eb\plain \f1\lang1033\fs24 . \emdash  (pp. 45\endash 46) K\u246 \'f6nige der Israeliten: \plain \f2\lang1032\fs24 \u7944 ?\u961 \'f1\u967 \'f7\u8052 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7961 ?\u946 \'e2\u961 \'f1\u945 \'e1\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u931 \'d3\u945 \'e1\u959 \'ef\u8058 ?\u955 \'eb\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7957 ?\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u7984 ?\u967 \'f7\u956 \'ec\u945 \'e1\u955 \'eb\u969 \'f9\u963 \'f3\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7993 ?\u949 \'e5\u961 \'f1\u959 \'ef\u965 \'f5\u963 \'f3\u945 \'e1\u955 \'eb\u8053 ?\u956 \'ec\plain \f1\lang1033\fs24 . \emdash  (pp. 47\endash 48) K\u246 \'f6nige von Babylon: \plain \f2\lang1032\fs24 \u927 \'cf\u7985 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u914 \'c2\u945 \'e1\u946 \'e2\u965 \'f5\u955 \'eb\u8182 ?\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u925 \'cd\u945 \'e1\u946 \'e2\u959 \'ef\u965 \'f5\u967 \'f7\u959 \'ef\u948 \'e4\u959 \'ef\u957 \'ed\u8057 ?\u963 \'f3\u959 \'ef\u961 \'f1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7957 ?\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7944 ?\u955 \'eb\u949 \'e5\u958 \'ee\u8049 ?\u957 \'ed\u948 \'e4\u961 \'f1\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u8051 ?\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24 . \emdash  (pp. 48\endash 50) Kaiser von Rom: \plain \f2\lang1032\fs24 \u927 \'cf\u7985 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u949 \'e5\u963 \'f3\u946 \'e2\u965 \'f5\u964 \'f4\u8051 ?\u961 \'f1\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8172 ?\u8061 ?\u956 \'ec\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1