\pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs24 (pp. 76\endash 86) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 R\u246 \'f6mische und byzantinische Kaiser:}}\plain \f1\lang1033\fs24  (pp. 76\endash 81) R\u246 \'f6mische Kaiser von Iulius Caesar bis zum Tetrarchie von Constantinus, Maximinus, Galerius und Maxentius: \plain \f2\lang1032\fs24 \u927 \'cf\u7985 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8054 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8172 ?\u969 \'f9\u956 \'ec\u945 \'e1\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 . \emdash  (pp. 81\endash 86) Byzantinische Kaiser von Konstantinos dem Gro\u223 \'dfen bis Alexios Murtzuphlos (1204): \plain \f2\lang1032\fs24 \u8013 ?\u963 \'f3\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u946 \'e2\u945 \'e1\u963 \'f3\u8055 ?\u955 \'eb\u949 \'e5\u965 \'f5\u963 \'f3\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u922 \'ca\u969 \'f9\u957 \'ed\u963 \'f3\u964 \'f4\u945 \'e1\u957 \'ed\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24 \-\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\u965 \'f5\u960 \'f0\u8057 ?\u955 \'eb\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u947 \'e3\u8049 ?\u955 \'eb\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u922 \'ca\u969 \'f9\u957 \'ed\u963 \'f3\u964 \'f4\u945 \'e1\u957 \'ed\u964 \'f4\u8055 ?\u957 \'ed\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24 .}

