\'e5\u955 \'eb\u949 \'e5\plain \f1\lang1033\fs24 \u8055 ?\plain \f3\lang1032\fs24 \u8115 ? \u925 \'cd\u953 \'e9\u954 \'ea\u951 \'e7\u966 \'f6\plain \f1\lang1033\fs24 \u8057 ?\plain \f3\lang1032\fs24 \u961 \'f1\u959 \'ef\u965 \'f5 \u8190 ?\u921 \'c9\u949 \'e5\u961 \'f1\u959 \'ef\u956 \'ec\u959 \'ef\u957 \'ed\u945 \'e1\u967 \'f7\u959 \'ef\u8166 ? \u964 \'f4\u959 \'ef\u8166 ? \u920 \'c8\u949 \'e5\u959 \'ef\u964 \'f4\plain \f1\lang1033\fs24 \u8057 ?\plain \f3\lang1032\fs24 \u954 \'ea\u959 \'ef\u965 \'f5 \u7972 ?\u948 \'e4\u951 \'e7 \u960 \'f0\u961 \'f1\u8182 ?\u964 \'f4\u959 \'ef\u957 \'ed \u964 \'f4\plain \f1\lang1033\fs24 \u8059 ?\plain \f3\lang1032\fs24 \u960 \'f0\u959 \'ef\u953 \'e9\u962 \'f2 \u7952 ?\u954 \'ea\u948 \'e4\u959 \'ef\u952 \'e8\plain \f1\lang1033\fs24 \u8051 ?\plain \f3\lang1032\fs24 \u957 \'ed\u964 \'f4\u945 \'e1, Leipzig 1770, S. 482\endash 520 (dort Sermo 85; zur Ausgabe siehe auch \plain \f1\i\lang1033\fs24 Lit\plain \f1\lang1033\fs24 ); CPG 7868.1; CPG 7869: \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 mut.\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Theotokes\plain \f1\lang1033\fs24 , S. 516, 8; \plain \f1\scaps\lang1033\fs24 Pirar, S. 476, 2\plain \f1\lang1033\fs24 ){\field{\*\fldinst HYPERLINK "hida://5650[0].5666g/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u967 \'f7\u945 \'e1\u961 \'f1\u953 \'e9\u963 \'f3\u956 \'ec\u8049 ?\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u956 \'ec\u8051 ?\u964 \'f4\u959 \'ef\u967 \'f7\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u957