\pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs24 (ff. 150\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 160\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Exodus}}\plain \f1\lang1033\fs24 , ed. \plain \f1\scaps\lang1033\fs24 Fischer 1767 \plain \f1\lang1033\fs24 (\plain \f1\i\lang1033\fs24 Lit\plain \f1\lang1033\fs24 ), S. 1\endash 26; Septuaginta Bd. II.1 (Cod. gr. 16, S. 11 nur erw\u228 \'e4hnt): \plain \f1\i\lang1033\fs24 inc. mut. \plain \f1\lang1033\fs24 (32, 17){\field{\*\fldinst HYPERLINK "hida://5650[0].5666g/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f3\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed \u966 \'f6\u969 \'f9\u957 \'ed\u8052 ?\u957 \'ed \u964 \'f4\u959 \'ef\u8166 ? \u955 \'eb\u945 \'e1\u959 \'ef\u8166 ? \u954 \'ea\u961 \'f1\u945 \'e1\u950 \'e6\u8057 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 des.\plain \f1\lang1033\fs24  (40, 32) \plain \f3\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u960 \'f0\u8049 ?\u963 \'f3\u945 \'e1\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u945 \'e1\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u950 \'e6\u965 \'f5\u947 \'e3\u945 \'e1\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24 . \emdash  Darunter: \plain \f3\lang1032\fs24 \u7956 ?\u958 \'ee\u959 \'ef\u948 \'e4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24 .
\par \pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Marginalien; Z\u228 \'e4hlung der Kapitel von \plain \f3\lang1032\fs20 \u927 \'cf\u915 \'c3\plain \f1\lang1033\fs20 \u884 ?\endash \plain \f3\lang1032\fs20 \u928 \'d0\u916 \'c4\plain \f1\lang1033\fs20 \u884 ? jeweils mit \u220 \'dcberschrift auf dem oberen und unteren Rand; Z\u228 \'e4hlung von \plain \f3\lang1032\fs20 \u931 \'d3\u920 \'c8\plain \f1\lang1033\fs20 \u884 ?\endash \plain \f3\lang1032\fs20 \u929 \'d1\u921 \'c9\plain \f1\lang1033\fs20 \u884 ? auf dem \u228 \'e4u\u223 \'dferen Rand: \plain \f1\i\lang1033\fs20 inc.\plain \f1\lang1033\fs20  (zu 32, 17):{\field{\*\fldinst HYPERLINK "hida://5650[1].5666g/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17  }}\plain \f1\lang1033\fs20 [\plain \f3\lang1032\fs20 \u927 \'cf\u915 \'c3\plain \f1\lang1033\fs20 \u884 ?] \plain \f3\lang1032\fs20 \u928 \'d0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u7936 ?\u957 \'ed\u949 \'e5\u955 \'eb\u8057 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u7953 ?\u945 \'e1\u965 \'f5\u964 \'f4\u959 \'ef\u8059 ?\u962 \'f2\plain \f1\lang1033\fs20 . \u8230 \'85 (zu 32, 29: \plain \f3\lang1032\fs20 \u7952 ?\u960 \'f0\u955 \'eb\u951 \'e7\u961 \'f1\u8061 ?\u963 \'f3\u945 \'e1\u964 \'f4\u949 \'e5\plain \f1\lang1033\fs20 ) \plain \f3\lang1032\fs20 \u7936 ?\u957 \'ed\u964 \'f4\u8054 ?\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u952 \'e8\u965 \'f5\u963 \'f3\u8055 ?\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u960 \'f0\u961 \'f1\u959 \'ef\u963 \'f3\u951 \'e7\plain \f1\lang1033\fs20 \-\plain \f3\lang1032\fs20 \u947 \'e3\u8049 ?\u947 \'e3\u949 \'e5\u964 \'f4\u949 \'e5\plain \f1\lang1033\fs20 , \plain \f3\lang1032\fs20 \u7972 ?\u964 \'f4\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u7969 ?\u947 \'e3\u953 \'e9\u8049 ?\u963 \'f3\u945 \'e1\u964 \'f4\u949 \'e5\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u964 \'f4\u8048 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u967 \'f7\u949 \'e5\u8150 ?\u961 \'f1\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u945 \'e1\u8016 ?\u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs20  ... (f. 152\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : zu 34, 20: \plain \f3\lang1032\fs20 \u964 \'f4\u953 \'e9\u956 \'ec\u8052 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u948 \'e4\u8061 ?\u963 \'f3\u949 \'e5\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs20 ) \plain \f3\lang1032\fs20 \u913 \'c1\u922 \'ca\plain \f1\lang1033\fs20 . \plain \f3\lang1032\fs20 \u964 \'f4\u949 \'e5\u957 \'ed\u959 \'ef\u957 \'ed\u964 \'f4\u959 \'ef\plain \f1\lang1033\fs20 \-\plain \f3\lang1032\fs20 \u954 \'ea\u959 \'ef\u960 \'f0\u8053 ?\u963 \'f3\u949 \'e5\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u945 \'e1\u8016 ?\u964 \'f4\u8057 ?\plain \f1\lang1033\fs20 . \plain \f3\lang1032\fs20 \u931 \'d3\u933 \'d5\plain \f1\lang1033\fs20 . \plain \f3\lang1032\fs20 \u964 \'f4\u961 \'f1\u945 \'e1\u967 \'f7\u951 \'e7\u955 \'eb\u959 \'ef\u954 \'ea\u959 \'ef\u960 \'f0\u8053 ?\u963 \'f3\u949 \'e5\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u945 \'e1\u8016 ?\u964 \'f4\u8057 ?\plain \f1\lang1033\fs20 . ... (zu 40, 20: \plain \f3\lang1032\fs20 \u963 \'f3\u965 \'f5\u957 \'ed\u8051 ?\u964 \'f4\u945 \'e1\u958 \'ee\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs20 ) \plain \f3\lang1032\fs20 \u7952 ?\u957 \'ed\u949 \'e5\u964 \'f4\u949 \'e5\u8055 ?\u955 \'eb\u945 \'e1\u964 \'f4\u959 \'ef\plain \f1\lang1033\fs20 .}

