\par \pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs20 Marginalien: \plain \f1\i\lang1033\fs20 inc.\plain \f1\lang1033\fs20  (zu 1, 1: \plain \f2\lang1032\fs20 \u948 \'e4\u965 \'f5\u963 \'f3\u956 \'ec\u945 \'e1\u8150 ?\u962 \'f2\plain \f1\lang1033\fs20 ){\field{\*\fldinst HYPERLINK "hida://5650[1].5666g/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17  }}\plain \f2\lang1032\fs20 \u913 \'c1\u922 \'ca\plain \f1\lang1033\fs20 . \plain \f2\lang1032\fs20 \u7952 ?\u957 \'ed\u959 \'ef\u956 \'ec\u945 \'e1\u955 \'eb\u949 \'e5\u8150 ?\plain \f1\lang1033\fs20  (!). (zu 1, 1: \plain \f2\lang1032\fs20 \u7952 ?\u961 \'f1\u965 \'f5\u952 \'e8\u961 \'f1\u8118 ?\u962 \'f2\plain \f1\lang1033\fs20 ) \plain \f2\lang1032\fs20 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7952 ?\u961 \'f1\u965 \'f5\u952 \'e8\u961 \'f1\u8118 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u952 \'e8\u945 \'e1\u955 \'eb\u8049 ?\u963 \'f3\u963 \'f3\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u959 \'ef\u8021 ?\u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u954 \'ea\u945 \'e1\u955 \'eb\u949 \'e5\u8150 ?\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u956 \'ec\u949 \'e5\u964 \'f4\u945 \'e1\u958 \'ee\u8058 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u945 \'e1\u953 \'e9\u948 \'e4\u8055 ?\u945 \'e1\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7944 ?\u961 \'f1\u945 \'e1\u946 \'e2\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7992 ?\u959 \'ef\u965 \'f5\u948 \'e4\u945 \'e1\u8055 ?\u94