\pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs24 (f. 285\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) <{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ioannes Bischof von Diokaisareia}}\plain \f1\lang1033\fs24 >, {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Verse auf den unbekannten Autor der Chronik}}\plain \f1\lang1033\fs24 , ed. \plain \f1\scaps\lang1033\fs24 Mencke\plain \f1\lang1033\fs24  1733, S. 62; \plain \f1\scaps\lang1033\fs24 Kolovou\plain \f1\lang1033\fs24  2010, S. 398\endash 399 (vgl.\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 auch \plain \f1\scaps\lang1033\fs24 Lachmann\plain \f1\lang1033\fs24  1834, S. IV\plain \f1\scaps\lang1033\fs24 ; W\plain \f1\scaps\lang1033\fs24 \u228 \'e4\plain \f1\scaps\lang1033\fs24 schke 1877, S. 263\plain \f1\scaps\lang1033\fs24 \endash \plain \f1\scaps\lang1033\fs24 268; \plain \f1\scaps\lang1033\fs24 Steinmann \plain \f1\lang1033\fs24 1914, Tafeln\plain \f1\scaps\lang1033\fs24 ; Lesm\plain \f1\scaps\lang1033\fs24 \u252 \'fc\plain \f1\scaps\lang1033\fs24 ller-Werner 1978, S. XXV\plain \f1\scaps\lang1033\fs24 \endash \plain \f1\scaps\lang1033\fs24 XXVI\plain \f1\lang1033\fs24 ): \plain \f3\lang1032\fs24 \u923 \'cb\u959 \'ef\u8150 ?\u963 \'f3\u952 \'e8\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u957 \'ed\u8052 ?\u961 \'f1\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7940 ?\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u8033 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7952 ?\u947 \'e3\u8060 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u961 \'f1\u8055 ?\u957 \'ed\u969 \'f9\plain \f1\lang1033\fs24  | \plain \f3\lang1032\fs24 \u915 \'c3\u949 \'e5\u969 \'f9\u961 \'f1\u947 \'e3\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u949 \'e5\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u966 \'f6\u951 \'e7\u956 \'ec\u8055 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\u966 \'f6\u8049 ?\u957 \'ed\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24  | \plain \f3\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u967 \'f7\u961 \'f1\u959 \'ef\u957 \'ed\u959 \'ef\u947 \'e3\u961 \'f1\u8049 ?\u966 \'f6\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 , \plain \f3\lang1032\fs24 \u964 \'f4\u8134 ?\u963 \'f3\u948 \'e4\u949 \'e5\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u946 \'e2\u8055 ?\u946 \'e2\u955 \'eb\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u960 \'f0\u8049 ?\u964 \'f4\u949 \'e5\u961 \'f1\plain \f1\lang1033\fs24 . | \plain \f3\lang1032\fs24 \u7992 ?\u969 \'f9\u8049 ?\u957 \'ed\u957 \'ed\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u963 \'f3\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u945 \'e1\u8059 ?\u964 \'f4\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u966 \'f6\u8055 ?\u955 \'eb\u949 \'e5\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u948 \'e4\u945 \'e1\u953 \'e9\u956 \'ec\u8057 ?\u957 \'ed\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  | \u8001 ? \plain \f3\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u960 \'f0\u961 \'f1\u959 \'ef\u8051 ?\u948 \'e4\u961 \'f1\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u960 \'f0\u961 \'f1\u8182 ?\u964 \'f4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24 , \plain \f3\lang1032\fs24 \u7936 ?\u955 \'eb\u955 \'eb\u8048 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u952 \'e8\u8059 ?\u964 \'f4\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  | \plain \f3\lang1032\fs24 \u916 \'c4\u953 \'e9\u959 \'ef\u954 \'ea\u945 \'e1\u953 \'e9\u963 \'f3\u945 \'e1\u961 \'f1\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7944 ?\u957 \'ed\u945 \'e1\u950 \'e6\u8049 ?\u961 \'f1\u946 \'e2\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24 . \emdash  Monokondylion: \plain \f3\lang1032\fs24 \u8008 ?\u955 \'eb\u8059 ?\u956 \'ec\u960 \'f0\u953 \'e9\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \u8001 ? \plain \f3\lang1032\fs24 \u8009 ?\u955 \'eb\u8059 ?\u956 \'ec\u960 \'f0\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24 . \emdash  Schm\u228 \'e4hverse auf den, der den Namen des Autors tilgte, siehe oben zu f. 248\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 : \plain \f3\lang1032\fs24 \u923 \'cb\u953 \'e9\u956 \'ec\u8183 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u945 \'e1\u954 \'ea\u8053 ?\u963 \'f3\u8131 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u946 \'e2\u961 \'f1\u8182 ?\u963 \'f3\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u8000 ?\u961 \'f1\u957 \'ed\u8051 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7956 ?\u963 \'f3\u951 \'e7\u953 \'e9\plain \f1\lang1033\fs24  | \plain \f3\lang1032\fs24 \u8005 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7952 ?\u958 \'ee\u8051 ?\u954 \'ea\u959 \'ef\u968 \'f8\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u961 \'f1\u967 \'f7\u8135 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8048 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u956 \'ec\u949 \'e5\u956 \'ec\u946 \'e2\u961 \'f1\u8049 ?\u957 \'ed\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  | \plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u8051 ?\u961 \'f1\u948 \'e4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7956 ?\u963 \'f3\u967 \'f7\u949 \'e5\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u960 \'f0\u955 \'eb\plain \f1\lang1033\fs24 \u8134 ?\plain \f3\lang1032\fs24 \u961 \'f1\u949 \'e5\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u954 \'ea\u959 \'ef\u946 \'e2\u959 \'ef\u965 \'f5\u955 \'eb\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  | \plain \f3\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u8051 ?\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u955 \'eb\u8134 ?\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7952 ?\u958 \'ee\u945 \'e1\u966 \'f6\u945 \'e1\u957 \'ed\u8055 ?\u963 \'f3\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24 . Darunter: \plain \f3\lang1032\fs24 \u959 \'ef\u8016 ?\u954 \'ea\plain \f1\lang1033\fs24 . \emdash  Zwischen der vorletzten und letzten Zeile sowie unter dieser steht folgender Text eines {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Symeon aus Theupolis}}\plain \f1\lang1033\fs24  (Antiocheia am Orontes): \plain \f3\lang1032\fs24 \u7960 ?\u947 \'e3\u8060 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u948 \'e4\u8050 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u957 \'ed\u949 \'e5\u960 \'f0\u955 \'eb\u8053 ?\u961 \'f1\u969 \'f9\u963 \'f3\u945 \'e1\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7952 ?\u954 \'ea\u954 \'ea\u949 \'e5\u954 \'ea\u959 \'ef\u