{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f2\lang1032\fs24 \u932 \'d4\u943 \'df\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u955 \'eb\u972 \'fc\u947 \'e3\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \u8038 ? \plain \f2\lang1032\fs24 \u931 \'d3\plain \f1\lang1033\fs24 \u8057 ?\u963 s\plain \f2\lang1032\fs24 \u963 \'f3\u953 \'e9\u949 \'e5\plain \f1\lang1033\fs24  (! = \plain \f2\lang1032\fs24 \u931 \'d3\plain \f1\lang1033\fs24 \u8061 ?\plain \f2\lang1032\fs24 \u963 \'f3\u953 \'e9\u949 \'e5\plain \f1\lang1033\fs24 ) \plain \f2\lang1032\fs24 \u931 \'d3\u949 \'e5\u957 \'ed\u949 \'e5\u954 \'ea\u943 \'df\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 des.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24 \u7984 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24  \u8004 ?\plain \f2\lang1032\fs24 \u957 \'ed\u965 \'f5\u967 \'f7\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u959 \'ef\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u951 \'e7\u955 \'eb\u972 \'fc\u962 \'f2\plain \f1\lang1033\fs24  \u7936 ?\plain \f2\lang1032\fs24 \u966 \'f6\u943 \'df\u954 \'ea\u951 \'e7\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24 . 
\par \pard\keepn\fi0\li0\tx225\tx450\qj\ri0\sb0\sa120\itap0 \plain \f1\lang1033\fs20 (f. 14\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) In margine zu S. 200 (82F) von Hand \u8222 \'84a\rdblquote  (s. \plain \f1\i\lang1033\fs20 S\plain \f1\lang1033\fs20 ) in zwei Halbkreisen geschrieben: \plain \f2\lang1032\fs20 \u928 \'d0\u955 \'eb\u8049 ?\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u8000 ?\u957 \'ed\u949 \'e5\plain \f1\lang1033\fs20 \u8055 ?\plain \f2\lang1032\fs20 \u961 \'f1\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u949 \'e5\u954 \'ea\u956 \'ec\plain \f1\lang1033\fs20 \u8051 ?\plain \f2\lang1032\fs20 \u961 \'f1\u949 \'e5\u963 \'f3\u952 \'e8\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs20  (!) \plain \f2\lang1032\fs20 \u954 \'ea\u961 \'f1\u949 \'e5\u8055 ?\u957 \'ed\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs20  (!?) \plain \f2\lang1032\fs20 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u968 \'f8\u965 \'f5\u967 \'f7\u8134 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u961 \'f1\u959 \'ef\u954 \'ea\u959 \'ef\u960 \'f0\u8052 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u948 \'e4\u953 \'e9\u8049 ?\u952 \'e8\u949 \'e5\u963 \'f3\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs20  (!). \plain \f2\lang1032\fs20 \u918 \'c6\plain \f1\lang1033\fs20 \u8053 ?\plain \f2\lang1032\fs20 \u957 \'ed\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u8000 ?\u957 \'ed\u949 \'e5\u8055 ?\u961 \'f1\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u961 \'f1\u959 \'ef\u954 \'ea\u959 \'ef\u960 \'f0\u964 \'f4\u949 \'e5\u8150 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u959 \'ef\u7988 ?\u948 \'e4\u949 \'e5\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u968 \'f8\u965 \'f5\u967 \'f7\u8134 ?\u962 \'f2\plain \f1\lang1033\fs20 . \emdash  (f. 33\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ) unter dem Text von Hand \u8222 \'84a\rdblquote  Einleitung zu einem nicht ausgef\u252 \'fchrten Apophtegma: \plain \f2\lang1032\fs20 \u917 \'c5\u7990 ?\u960 \'f0\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs20  \u8001 ? \plain \f2\lang1032\fs20 \u7936 ?\u946 \'e2\u946 \'e2\u8048 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u924 \'cc\u945 \'e1\u961 \'f1\plain \f1\lang1033\fs20 .}

