\par \pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 (f. 3\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  (Cap. 7, 26, zu 317D2: \plain \f2\lang1032\fs24 \u932 \'d4\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u8048 ?\u961 \'f1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8002 ?\u957 \'ed\plain \f1\lang1033\fs24  ...){\field{\*\fldinst HYPERLINK "hida://5650[0].5666g/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f2\lang1032\fs24 \u932 \'d4\u8055 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u8004 ?\u957 \'ed\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u8183 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u966 \'f6\u8059 ?\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  [\plain \f2\lang1032\fs24 \u8017 ?\u960 \'f0\u8049 ?\u961 \'f1\plain \f1\lang1033\fs24 ]\plain \f2\lang1032\fs24 \u967 \'f7\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7937 ?\u960 \'f0\u955 \'eb\u959 \'ef\u8166 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u7990 ?\u957 \'ed\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24 . \emdash  (f. 3\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) (Cap. 8, 6, zu 320A8: \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u8049 ?\u964 \'f4\u969 \'f9\plain \f1\lang1033\fs24  ...) [\plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 