051 ?\plain \f2\lang1032\fs24 \u960 \'f0\u969 \'f9\u957 \'ed \u960 \'f0\u961 \'f1\u959 \'ef\u966 \'f6\plain \f1\lang1033\fs24 \u8053 ?\plain \f2\lang1032\fs24 \u964 \'f4\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 des. mut. \plain \f1\lang1033\fs24 (4. Ode, 2. Trop.) \u7944 ?\plain \f2\lang1032\fs24 \u947 \'e3\u8049 ?\u955 \'eb\u955 \'eb\u959 \'ef\u965 \'f5 \u931 \'d3\u959 \'ef\u955 \'eb\u959 \'ef\u956 \'ec\u959 \'ef\u957 \'ed\u8052 ? ... \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24 \u8166 ? \plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24 \u8057 ?\plain \f2\lang1032\fs24 \u956 \'ec\u959 \'ef\u965 \'f5 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs24 \u8058 ?\plain \f2\lang1032\fs24 \u962 \'f2 \u954 \'ea\u945 \'e1\u961 \'f1\u960 \'f0\u959 \'ef\plain \f1\lang1033\fs24 \u8059 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24 .}

