\pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs24 (Recto) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lesest\u252 \'fccke f\u252 \'fcr den 6. August (Verkl\u228 \'e4rung des Herrn)}}\plain \f1\lang1033\fs24 : (f. H\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 des. mut.\plain \f1\lang1033\fs24  (Lc 9, 36) \plain \f3\lang1032\fs24 \u959 \'ef\u8016 ?\u948 \'e4\u949 \'e5\u957 \'ed\u8054 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u960 \'f0\u8053 ?\u947 \'e3\u947 \'e3\u949 \'e5\u953 \'e9\u955 \'eb\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7952 ?\u954 \'ea\u949 \'e5\u8055 ?\u957 \'ed\u945 \'e1\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u945 \'e1\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7969 ?\u956 \'ec\u8051 ?\u961 \'f1\u945 \'e1\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u959 \'ef\u8016 ?\u948 \'e4\u8050 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u8038 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7953 ?\u969 \'f9\u961 \'f1\u8049 ?\u954 \'ea\u945 \'e1\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24 . \emdash  (H\plain \f1\super\lang1033\fs24 ra\endash vb\plain \f1\lang1033\fs24 ) Lesung f\u252 \'fcr die Liturgie aus dem Matthaeus-Evangelium, in der Hs. f\u228 \'e4lschlich als Marcus-Evangelium bezeichnet: Auf dem oberen Rand: \plain \f3\lang1032\fs24 \u917 \'c5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u955 \'eb\u949 \'e5\u953 \'e9\u964 \'f4\u959 \'ef\u965 \'f5\u961 \'f1\u947 \'e3\u8055 ?\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24 ; \u252 \'fcber dem Text: >\plain \f3\lang1032\fs24 \u7960 ?\u954 \'ea\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u924 \'cc\u8049 ?\u961 \'f1\u954 \'ea\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  (!)<, \plain \f1\i\lang1033\fs24 inc. \plain \f1\lang1033\fs24 (Mt 17, 1\endash 9){\field{\*\fldinst HYPERLINK "hida://5650[0].5666g/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f1\lang1033\fs24 >\plain \f3\lang1032\fs24 \u932 \'d4\plain \f1\lang1033\fs24 <\u8183 ? \plain \f3\lang1032\fs24 \u954 \'ea\u945 \'e1\u953 \'e9\u961 \'f1\u8183 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7952 ?\u954 \'ea\u949 \'e5\u8055 ?\u957 \'ed\u8179 ? \u960 \'f0\u945 \'e1\u961 \'f1\u945 \'e1\u955 \'eb\u945 \'e1\u956 \'ec\u946 \'e2\u940 \'dc\u957 \'ed\u949 \'e5\u953 \'e9 \u8001 ? \u7992 ?\u951 \'e7\u963 \'f3\u959 \'ef\u8166 ?\u962 \'f2 \u964 \'f4\u8056 ?\u957 \'ed \u928 \'d0\u941 \'dd\u964 \'f4\u961 \'f1\u959 \'ef\u957 \'ed \u954 \'ea\u945 \'e1\u8054 ? \u7992 ?\u940 \'dc\u954 \'ea\u969 \'f9\u946 \'e2\u959 \'ef\u957 \'ed \u954 \'ea\u945 \'e1\u8054 ? \u7992 ?\u969 \'f9\u940 \'dc\u957 \'ed\u957 \'ed\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 des.\plain \f1\lang1033\fs24  (Mt. 17, 9) \plain \f3\lang1032\fs24 \u7952 ?\u954 \'ea\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u957 \'ed\u949 \'e5\u954 \'ea\u961 \'f1\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u963 \'f3\u964 \'f4\u8150 ?\plain \f1\lang1033\fs24  (! = \plain \f3\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u963 \'f3\u964 \'f4\u8135 ?\plain \f1\lang1033\fs24 ). \emdash  (Verso) Hinweise zu den Lesungen f\u252 \'fcr den 7.\endash 9. August: 7. August: \plain \f3\lang1032\fs24 \u917 \'c5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u957 \'ed\u8049 ?\u956 \'ec\u957 \'ed\u951 \'e7\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u946 \'e2\u945 \'e1\u961 \'f1\u946 \'e2\u8049 ?\u961 \'f1\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  ... . \emdash  8. August (Aemilianus von Cyzicus [gest. 818]): \plain \f3\lang1032\fs24 \u917 \'c5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7941 ?\u947 \'e3\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u913 \'c1\u7984 ?\u956 \'ec\u953 \'e9\u955 \'eb\u953 \'e9\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24 \u8056 ?\plain \f3\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24  ... . \emdash  9. August (Apostel Matthias): \plain \f1\i\lang1033\fs24 des.\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u917 \'c5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7937 ?\u947 \'e3\u8055 ?\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u7936 ?\u960 \'f0\u8057 ?\u963 \'f3\u964 \'f4\u959 \'ef\u955 \'eb\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u924 \'cc\u945 \'e1\u964 \'f4\u952 \'e8\u8055 ?\u945 \'e1\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u950 \'e6\u951 \'e7\u964 \'f4\u949 \'e5\plain \f1\lang1033\fs24 \u8150 ? \plain \f3\lang1032\fs24 \u7944 ?\u960 \'f0\u961 \'f1\u953 \'e9\u955 \'eb\u955 \'eb\u8055 ?\u8179 ?\plain \f1\lang1033\fs24  \plain \f3\lang1032\fs24 \u954 \'ea\u949 \'e5\u884 ?\plain \f1\lang1033\fs24 .}

