\pard\sl360\slmult1\fi-420\li420\tx420\qj\ri0\sb195\sa0\itap0 \plain \f1\b\i\lang1033\fs20 Kat  \plain \f1\scaps\lang1033\fs20 Gardthausen\plain \f1\lang1033\fs20 , S. 78\endash 81. \emdash  G.\plain \f1\b\lang1033\fs20  \plain \f1\lang1033\fs20 G\plain \f1\scaps\lang1033\fs20 oldschmidt, \plain \f1\lang1033\fs20 Catalogue des Manuscrits Alchimiques Grecs, IV, Br\u252 \'fcssel 1932, \plain \f1\scaps\lang1033\fs20 S. 222\plain \f1\scaps\lang1033\fs20 \endash \plain \f1\scaps\lang1033\fs20 246\plain \f1\scaps\lang1033\fs20 . \plain \f1\scaps\lang1033\fs20 \emdash \plain \f1\scaps\lang1033\fs20  \plain \f1\scaps\lang1033\fs20 K. \plain \f1\scaps\lang1033\fs20 Hajd\plain \f1\scaps\lang1033\fs20 \u250 \'fa\plain \f1\scaps\lang1033\fs20 , \plain \f1\lang1033\fs20 Katalog der griechischen Handschriften der BSB M\u252 \'fcnchen\plain \f1\scaps\lang1033\fs20 , III: \plain \f1\lang1033\fs20 Cod. Graec. Monac. 110\endash 180, Wiesbaden 2003, S. 33\endash 42.
\par \pard\sl360\slmult1\fi-420\li420\tx420\qj\ri0\sb195\sa0\itap0 \plain \f1\b\i\lang1033\fs20 Lit  \plain \f1\scaps\lang1033\fs20 M. Berthe\plain \f1\scaps\lang1033\fs20 lot \plain \f1\scaps\lang1033\fs20 \endash \plain \f1\scaps\lang1033\fs20  C. E. Ruelle,\plain \f1\lang1033\fs20  Collection des anciens alchimistes grecs: I, Introduction, S. 193\endash 194 (Cod. gr. 66 erw\u228 \'e4hnt); II: Texte grec, Paris 1888.\emdash  \plain \f1\scaps\lang1033\fs20 Diels II, S. 24, 95\plain \f1\scaps\lang1033\fs20 \endash \plain \f1\scaps\lang1033\fs20 18\plain \f1\lang1033\fs20  \emdash  \plain \f1\scaps\lang1033\fs20 A. J.\plain \f1\scaps\lang1033\fs20  Festugi\plain \f1\scaps\lang1033\fs20 \u232 \'e8\plain \f1\scaps\lang1033\fs20 re\plain \f1\lang1033\fs20 , Alchymica, in: L\lquote Antiquit\u233 \'e9 Classique 8 (1939), S. 71\endash 95, bes. S. 83\endash 84. \emdash  \plain \f1\scaps\lang1033\fs20 A.\plain \f1\scaps\lang1033\fs20  Rehm\plain \f1\lang1033\fs20 , Zur \u220 \'dcberlieferung der griechischen Alchemisten, in: BZ 39 (1939), S. S. 394\endash 434, bes. 416\endash 417. \emdash  \plain \f1\scaps\lang1033\fs20 M. Martelli \plain \f1\scaps\lang1033\fs20 \endash \plain \f1\scaps\lang1033\fs20  T. Dorandi \plain \f1\lang1033\fs20 (Hrsg.), Pseudo-Democrito. Scritti alchemici con il commentario di Sinesio (Textes et travaux de Chrysopoeia 12), Paris\endash Mailand, 2011 (Hs. nicht erw\u228 \'e4hnt)\plain \f3\lang1033\fs20 .\plain \f1\lang1033\fs20  \emdash  \plain \f1\scaps\lang1033\fs20 G. Kofterid\plain \f1\scaps\lang1033\fs20 u\plain \f1\lang1033\fs20 , Beschreibung w\u228 \'e4hrend eines Praktikums 2016\plain \f1\scaps\lang1033\fs20 . \plain \f1\scaps\lang1033\fs20 \emdash \plain \f1\scaps\lang1033\fs20  Touwaide\plain \f1\lang1033\fs20 , S. 108 [0470]\plain \f1\lang1033\fs24 . }

