\pard\sl360\slmult1\fi-420\li420\tx420\qj\ri0\sb195\sa0\itap0 \plain \f1\b\i\lang1033\fs20 E  \plain \f1\lang1033\fs20 Pappdeckeleinband, mit dunkelgr\u252 \'fcnem, schwarzgesprengseltem {\field{\*\fldinst HYPERLINK "hida://5260[0]/"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Buntpapier}}\plain \f1\lang1033\fs20  bezogen; R\u252 \'fccken mit Leder verst\u228 \'e4rkt. Auf dem R\u252 \'fccken unter dem Schild mit der heute g\u252 \'fcltigen Signatur, rotes Titelschild mit Aufschrift \plain \f1\i\lang1033\fs20 GALENUS\plain \f1\lang1033\fs20  in Gold.}

