\par \pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 (ff. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Homilia XXXIII: \plain \f2\lang1032\fs24 \u932 \'d4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u947 \'e3\u953 \'e9\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u921 \'c9\u969 \'f9\u945 \'e1\u957 \'ed\u957 \'ed\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u961 \'f1\u967 \'f7\u953 \'e9\u949 \'e5\u960 \'f0\u953 \'e9\u963 \'f3\u954 \'ea\u959 \'ef\u960 \'f0\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u922 \'ca\u969 \'f9\u957 \'ed\u963 \'f3\u964 \'f4\u945 \'e1\u957 \'ed\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24 \-\plain \f2\lang1032\fs24 \u957 \'ed\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24 \-\plain \f2\lang1032\fs24 \u960 \'f0\u959 \'ef\u955 \'eb\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u961 \'f1\u956 \'ec\u951 \'e7\u957 \'ed\u951 \'e7\u953 \'e9\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u945 \'e1\u964 \'f4\u952 \'e8\u961 \'f1\u945 \'e1\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u965 \'f5\u945 \'e1\u947 \'e3\u947 \'e3\u949 \'e5\u955 \'eb\u953 \'e9\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  (\plain \f1\i\lang1033\fs24 10, 16\plain \f1\lang1033\fs24 ){\field{\*\fldinst HYPERLINK "hida://5650[0].5666g/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f2\lang1032\fs24 \u7992 ?\u948 \'e4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u947 \'e3\u969 \'f9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u945 \'e1\u960 \'f0\u959 \'ef\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u949 \'e5\u955 \'eb\u955 \'eb\u969 \'f9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u965 \'f5\u956 \'ec\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  ... .. \emdash  (ff. 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 33\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Homilia XXXV: \plain \f2\lang1032\fs24 \u932 \'d4\u959 \'ef\u8166 ? \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\u8166 ? \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2 \u946 \'e2\u884 ?\plain \f1\lang1033\fs24 . \emdash  (ff. 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 43\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Homilia XXXVI (XXXVII). \emdash  (ff. 44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Homilia XXXVII (XXXVIII). \emdash  (ff. 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 73\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Homilia XLI, \plain \f1\i\lang1033\fs24 des. mut.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u963 \'f3\u964 \'f4\u953 \'e9\u957 \'ed \u964 \'f4\u959 \'ef\u948 \'e4\u949 \'e5 \u949 \'e5\u961 \'f1\u947 \'e3\u959 \'ef\plain \f1\super\lang1033\fs24 \endash \plain \f1\lang1033\fs24 . \emdash  (ff. 73\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Homilia XLII. \emdash  (ff. 83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 98\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Homilia XLIII. \emdash  (ff. 98\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 107\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Homilia XLVI. \emdash  (ff. 108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Homilia LXXIII, \plain \f1\i\lang1033\fs24 des. \plain \f2\lang1032\fs24 \u960 \'f0\u965 \'f5\u961 \'f1 \u945 \'e1\u963 \'f3\u946 \'e2\u949 \'e5\u963 \'f3\u964 \'f4\u959 \'ef\plain \f1\super\lang1033\fs24 \endash \plain \f2\lang1032\fs24  \u954 \'ea\plain \f1\lang1033\fs24 (\plain \f2\lang1032\fs24 \u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24 )\plain \f2\lang1032\fs24  \u948 \'e4\u953 \'e9\u945 \'e1\u946 \'e2\u955 \'eb\u949 \'e5\u968 \'f8\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed \u960 \'f0\u961 \'f1\u959 \'ef\u962 \'f2 \u964 \'f4\u945 \'e1 \u956 \'ec\u949 \'e5\u955 \'eb\u955 \'eb\u959 \'ef\u957 \'ed\u964 \'f4\u945 \'e1 \u903 ? \u953 \'e9\u957 \'ed\u945 \'e1 \u954 \'ea\plain \f1\lang1033\fs24 (\plain \f2\lang1032\fs24 \u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24 )\plain \f2\lang1032\fs24  \u964 \'f4\u969 \'f9\plain \f1\super\lang1033\fs24 \endash \plain \f2\lang1032\fs24  \u945 \'e1\u953 \'e9\u969 \'f9\u957 \'ed\u953 \'e9\plain \f1\lang1033\fs24 (\plain \f2\lang1032\fs24 \u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 )\plain \f2\lang1032\fs24  \u7937 ?\u960 \'f0\u953 \'e9\u964 \'f4\u965 \'f5\u967 \'f7\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed \plain \f1\lang1033\fs24 (ante corr.)\plain \f2\lang1032\fs24  \u945 \'e1\u947 \'e3\u945 \'e1\u952 \'e8\u969 \'f9\u957 \'ed \u967 \'f7\u945 \'e1\u961 \'f1\u953 \'e9\u964 \'f4\u953 \'e9 ... .\plain \f1\lang1033\fs24  \emdash  (ff. 118\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 : Homilia LXXIX. \emdash  (ff. 129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): Homilia LXXX, \plain \f1\i\lang1033\fs24 des. mut. \plain \f2\lang1032\fs24 \u949 \'e5\u957 \'ed\u964 \'f4\u945 \'e1\u965 \'f5\u952 \'e8\u945 \'e1 \u960 \'f0\u955 \'eb\u959 \'ef\u965 \'f5\u964 \'f4\u969 \'f9\plain \f1\lang1033\fs24 . \emdash  (ff. 140\plain \f1\super\lang1033\fs24 