\par \pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 (IV\plain \f1\super\lang1033\fs20 rv\plain \f1\lang1033\fs20 ) Iosua 10, 39\endash 11, 8, \plain \f1\scaps\lang1033\fs20 Tischendorf\plain \f1\lang1033\fs20 , S. 161\endash 162: \plain \f1\i\lang1033\fs20 inc. \plain \f1\lang1033\fs20 (39) [\u8230 \'85] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f3\lang1032\fs20\chcbpat17 \u955 \'eb.\u956 \'ec\u957 \'ed\u945 \'e1 \u954 \'ea\u945 \'e1\u8054 ? \u964 \'f4\u8183 ? \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8150 ? \u945 \'e1\u8016 ?\u964 \'f4\u8134 ?\u962 \'f2 (40) \u922 \'ca\u945 \'e1\u8054 ? \u7952 ?\u960 \'f0\u8049 ?\u964 \'f4\u945 \'e1\u958 \'ee\u949 \'e5\u957 \'ed}}\plain \f1\lang1033\fs20  \u8230 \'85 \plain \f1\i\lang1033\fs20 des.\plain \f1\lang1033\fs20  (11, 8) \plain \f3\lang1032\fs20 \u954 \'ea\u972 \'fc\u960 \'f0\u964 \'f4\u959 \'ef\u957 \'ed\u964 \'f4\u949 \'e5\u962 \'f2\plain \f1\lang1033\fs20  [\plain \f3\lang1032\fs20 \u945 \'e1\plain \f1\lang1033\fs20 \u8016 ?\plain \f3\lang1032\fs20 \u964 \'f4\u959 \'ef\plain \f1\lang1033\fs20 \u8058 ?\plain \f3\lang1032\fs20 \u962 \'f2\plain \f1\lang1033\fs20 ].\emdash  (f. V\plain \f1\super\lang1033\fs20 r\endash v\plain \f1\lang1033\fs20 ) 11, 8\endash 16, \plain \f1\scaps\lang1033\fs20 Tischendorf\plain \f1\lang1033\fs20 , S. 163\endash 164: \plain \f1\i\lang1033\fs20 inc.\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f3\lang1032\fs20\chcbpat17 \u954 \'ea\u945 \'e1\u964 \'f4\u8051 ?\u948 \'e4\u953 \'e9\u969 \'f9\u954 \'ea\u959 \'ef\u957 \'ed \u7957 ?\u969 \'f9\u962 \'f2 \u931 \'d3\u953 \'e9\u948 \'e4\u8182 ?\u957 \'ed\u959 \'ef\u962 \'f2 \u964 \'f4\u8134 ?\u962 \'f2 \u956 \'ec\u949 \'e5\u947 \'e3\u940 \'dc\u955 \'eb\u951 \'e7\u962 \'f2}}\plain \f1\lang1033\fs20  \u8230 \'85\plain \f2\lang1033\fs20  \plain \f1\i\lang1033\fs20 des.\plain \f1\lang1033\fs20  \plain \f3\lang1032\fs20 \u9