ain \f1\lang1033\fs24 ) Evangelium: >\plain \f2\lang1032\fs24 \u917 \'c5\u8016 ?\u945 \'e1\u947 \'e3\u947 \'e3\u8051 ?\u955 \'eb\u953 \'e9\u959 \'ef\u957 \'ed \u7941 ?\u947 \'e3\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u8048 ? \u7992 ?\u969 \'f9\u8049 ?\u957 \'ed\u957 \'ed\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs24 <, \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f2\lang1032\fs24\chcbpat17 >\u7960 ?<\u957 \'ed \u7936 ?\u961 \'f1\u967 \'f7\u8135 ? \u7974 ?\u957 \'ed \u8001 ? \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 des.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u959 \'ef\u8016 ?\u948 \'e4\plain \f1\lang1033\fs24 \rquote  \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u959 \'ef\u7990 ?\u956 \'ec\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u8057 ?\u963 \'f3\u956 \'ec\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u967 \'f7\u969 \'f9\u961 \'f1\u8134 ?\u963 \'f3\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u8057 ?\u956 \'ec\u949 \'e5\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u8055 ?\u946 \'e2\u955 \'eb\u953 \'e9\u945 \'e1\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u7936 ?\u956 \'ec\u8053 ?\u957 \'ed\plain \f1\lang1033\fs24 . \emdash  Darunter: >\plain \f2\lang1032\fs24 \u917 \'c5\u8016 ?\u945 \'e1\u947 \'e3\u947 \'e3\u8051 ?\u955 \'eb\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7940 ?\u947 \'e3\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7992 ?\u969 \'f9\u8049 ?\u957 \'ed\u957 \'ed\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u8055 ?\u967 \'f7\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u885 ?\u946 \'e2\u947 \'e3\u884 ?\plain \f1\lang1033\fs24 .
\par \pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 (ff. 355\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 356\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Perikope von der Ehebrecherin}}\plain \f1\lang1033\fs24 : \plain \f1\b\lang1033\fs24 Ioannes\plain \f1\lang1033\fs24 , 7, 53\endash 8, 11 (Hinweis von sp\u228 \'e4terer Hand auf diesen Text auf f. 309\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), vgl. zur Textgeschichte \plain \f1\scaps\lang1033\fs24 Von Soden, I.1,\plain \f1\lang1033\fs24  S. 486\endash 526: \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  (Io \plain \f2\lang1032\fs24 7, 53) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f2\lang1032\fs24\chcbpat17 \u922 \'ca\u945 \'e1\u8054 ? \u7952 ?\u960 \'f0\u959 \'ef\u961 \'f1\u949 \'e5\u973 \'fd\u952 \'e8\u951 \'e7 \u7957 ?\u954 \'ea\u945 \'e1\u963 \'f3\u964 \'f4\u959 \'ef\u962 \'f2 \u949 \'e5\u7984 ?\u962 \'f2 \u964 \'f4\u8056 ?\u957 \'ed \u964 \'f4}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8057 ?}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666v/?u"}{\fldrslt \plain \f2\lang1032\fs24\chcbpat17 \u960 \'f0\u959 \'ef\u957 \'ed \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\u8166 ?. (Io 8, 1) \u7992 ?\u951 \'e7\u963 \'f3\u959 \'ef\u8166 ?\u962 \'f2 \u948 \'e4\u8050 ? \u7952 ?\u960 \'f0\u959 \'ef\u961 \'f1\u949 \'e5\u973 \'fd\u952 \'e8\u951 \'e7 \u949 \'e5\u7984 ?\u962 \'f2 \u964 \'f4\u8056 ? \u8012 ?\u961 \'f1\u959 \'ef\u962 \'f2 \u964 \'f4\u8182 ?\u957 \'ed \u7960 ?\u955 \'eb\u945 \'e1\u953 \'e9\u8182 ?\u957 \'ed}}\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 des. \plain \f1\lang1033\fs24 (Io 8, 11) \plain \f2\lang1032\fs24 \u927 \'cf\u8016 ?\u948 \'e4\u8050 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u947 \'e3\u974 \'fe\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u961 \'f1\u943 \'df\u957 \'ed\u969 \'f9\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u960 \'f0\u959 \'ef\u961 \'f1\u949 \'e5\u973 \'fd\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u951 \'e7\u954 \'ea\u941 \'dd\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7937 ?\u956 \'ec\u940 \'dc\u961 \'f1\u964 \'f4\u945 \'e1\u957 \'ed\u949 \'e5\plain \f1\lang1033\fs24 . \emdash  Darunter: >\plain \f2\lang1032\fs24 \u932 \'d4\u8056 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7992 ?\u969 \'f9\u8049 ?\u957 \'ed\u957 \'ed\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7941 ?\u947 \'e3\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u945 \'e1\u947 \'e3\u947 \'e3\u941 \'dd\u955 \'eb\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u958 \'ee\u949 \'e5\u948 \'e4\u8057 ?\u952 \'e8\u951 \'e7\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u967 \'f7\u961 \'f1\u8057 ?\u957 \'ed\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u955 \'eb\u946 \'e2\u884 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u955 \'eb\u8053 ?\u968 \'f8\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs2