\pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs24 (f. {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 17}}\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u952 \'e8\u949 \'e5\u957 \'ed\u949 \'e5\u946 \'e2\u959 \'ef\u965 \'f5\u963 \'f3\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u965 \'f5\u957 \'ed\u945 \'e1\u8150 ?\u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24 , ed. \plain \f1\scaps\lang1033\fs24 C. Bursian\plain \f1\lang1033\fs24 , Fragmentum medicum graecum, in: Index Scholarum Hibernarum Publice et Privatum in Universitate Litterarum Ienensi, Jena 1873\endash 1874, S. 3\endash 14 (https://babel.hathitrust.org/cgi/pt?id=hvd.32044085079135), vgl. auch \plain \f1\scaps\lang1033\fs24 Bursian\plain \f1\lang1033\fs24  1861 (\plain \f1\i\lang1033\fs24 Lit\plain \f1\lang1033\fs24 ), S. 23, Anm. zu S. 18: \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u952 \'e8\u949 \'e5\u957 \'ed\u949 \'e5\u946 \'e2\u959 \'ef\u8059 ?\u963 \'f3\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  (!= \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u952 \'e8\u949 \'e5\u957 \'ed\u949 \'e5\u965 \'f5\u959 \'ef\u8059 ?\u963 \'f3\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24 ), \plain \f1\i\lang1033\fs24 inc.\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u915 \'c3\u965 \'f5\u957 \'ed\u945 \'e1\u8150 ?\u954 \'ea\u945 \'e1\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u957 \'ed\u8182 ?\u957 \'ed\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24  \u7970 ? \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u952 \'e8\u8051 ?\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u963 \'f3\u964 \'f4\u8055 ?\u957 \'ed\plain \f1\lang1033\fs24  \u7970 ? \plain \f2\lang1032\fs24 \u959 \'ef\u8016 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u964 \'f4\u949 \'e5\u956 \'ec\u8055 ?\u963 \'f3\u953 \'e9\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8057 ?\u963 \'f3\u966 \'f6\u949 \'e5\u961 \'f1\u949 \'e5\plain \f1\lang1033\fs24  ... \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\u8055 ?\u955 \'eb\u965 \'f5\u963 \'f3\u949 \'e5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u948 \'e4\u961 \'f1\u8057 ?\u947 \'e3\u965 \'f5\u957 \'ed\u959 \'ef\u957 \'ed\u903 ?\plain \f1\lang1033\fs24  ... \plain \f2\lang1032\fs24 \u954 \'ea\u8049 ?\u968 \'f8\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24  (!) \plain \f2\lang1032\fs24 \u967 \'f7\u8059 ?\u964 \'f4\u961 \'f1\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u7940 ?\u955 \'eb\u965 \'f5\u966 \'f6\u949 \'e5\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24  \plain \f2\lang1032\fs24 \u954 \'ea\u949 \'e5\u966 \'f6\u945 \'e1\u955 \'eb\u8053 ?\u957 \'ed\plain \f1\lang1033\fs24 .}

