\par \pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs20 Darunter von anderer Hand sehr unorthographisch: \u8001 ? \plain \f2\lang1032\fs20 \u954 \'ea\plain \f1\lang1033\fs20 \u8059 ?\plain \f2\lang1032\fs20 \u961 \'f1\u953 \'e9\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u917 \'c5\u921 \'c9\u921 \'c9\plain \f1\lang1033\fs20 (\plain \f2\lang1032\fs20 \u963 \'f3\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20 )\plain \f2\lang1032\fs20 \u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u935 \'d7\plain \f1\lang1033\fs20 (\plain \f2\lang1032\fs20 \u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\plain \f1\lang1033\fs20 \u8057 ?)\plain \f2\lang1032\fs20 \u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u956 \'ec\plain \f1\lang1033\fs20 \u8118 ?\plain \f2\lang1032\fs20 \u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u949 \'e5\plain \f1\lang1033\fs20 \u8016 ?\plain \f2\lang1032\fs20 \u955 \'eb\plain \f1\lang1033\fs20 \u8057 ?\plain \f2\lang1032\fs20 \u947 \'e3\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u966 \'f6\u945 \'e1\u957 \'ed\u949 \'e5\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u957 \'ed\u945 \'e1\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u948 \'e4\u953 \'e9\u945 \'e1\u955 \'eb\u955 \'eb\u945 \'e1\u958 \'ee\u959 \'ef\u956 \'ec\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs20  (?) \plain \f2\lang1032\fs20 \u964 \'f4\plain \f1\lang1033\fs20 \u8056 ?\plain \f2\lang1032\fs20 \u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u945 \'e1\u955 \'eb\u945 \'e1\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs20  \u7940 ?(\plain \f2\lang1032\fs20 \u957 \'ed\u952 \'e8\u961 \'f1\u969 \'f9\u960 \'f0\u959 \'ef\plain \f1\lang1033\fs20 )\plain \f2\lang1032\fs20 \u957 \'ed\plain \f1\lang1033\fs20 . [\u8230 \'85]\plain \f2\lang1032\fs20 \u956 \'ec\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs20  \pl