\'e1\u962 \'f2\plain \f1\lang1033\fs20 , \plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u947 \'e3\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f2\lang1032\fs20 \u7944 ?\u957 \'ed\u8051 ?\u964 \'f4\u949 \'e5\u953 \'e9\u955 \'eb\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7952 ?\u8048 ?\u961 \'f1\plain \f1\lang1033\fs20  ... . \emdash  Donnerstag, TR, S. 69\endash 70: >\plain \f2\lang1032\fs20 \u932 \'d4\u8135 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u949 \'e5\u884 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u961 \'f1\u969 \'f9\u8147 ?\plain \f1\lang1033\fs20 , \plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u947 \'e3\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f2\lang1032\fs20 \u7964 ?\u955 \'eb\u945 \'e1\u956 \'ec\u968 \'f8\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7952 ?\u947 \'e3\u954 \'ea\u961 \'f1\u945 \'e1\u964 \'f4\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs20  ... . \emdash  >\plain \f2\lang1032\fs20 \u7961 ?\u963 \'f3\u960 \'f0\u8051 ?\u961 \'f1\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs20 , \plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u946 \'e2\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f1\lang1033\fs20 \u8009 ? \plain \f2\lang1032\fs20 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u954 \'ea\u965 \'f5\u961 \'f1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u963 \'f3\u964 \'f4\u945 \'e1\u965 \'f5\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs20  ... . \emdash  Freitag, TR, S. 79, 84: >\plain \f2\lang1032\fs20 \u932 \'d4\u8135 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u928 \'d0\u945 \'e1\u961 \'f1\u945 \'e1\u963 \'f3\u954 \'ea\u949 \'e5\u965 \'f5\u8052 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u961 \'f1\u969 \'f9\u8147 ?\plain \f1\lang1033\fs20 , \plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u955 \'eb\plain \f1\lang1033\fs20 . \plain \f2\lang1032\fs20 \u946 \'e2\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f2\lang1032\fs20 \u928 \'d0\u961 \'f1\u8056 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u963 \'f3\u969 \'f9\u964 \'f4\u951 \'e7\u961 \'f1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20  \u8230 \'85 . >\plain \f2\lang1032\fs20 \u7961 ?\u963 \'f3\u960 \'f0\u8051 ?\u961 \'f1\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs20 , \plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u946 \'e2\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f2\lang1032\fs20 \u922 \'ca\u945 \'e1\u952 \'e8\u945 \'e1\u961 \'f1\u8055 ?\u963 \'f3\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7953 ?\u945 \'e1\u965 \'f5\u964 \'f4\u959 \'ef\u8058 ?\u962 \'f2\plain \f1\lang1033\fs20  ... . 
\par \pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 (ff.\~123\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 125\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) Sonntag der Tyrophagie: TR, S. 107\endash 108 (D, ff.\~193\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 194\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ): >\plain \f2\lang1032\fs20 \u932 \'d4\u8135 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u954 \'ea\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u8135 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u965 \'f5\u961 \'f1\u959 \'ef\u966 \'f6\u8049 ?\u947 \'e3\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20 <, \plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u955 \'eb\plain \f1\lang1033\fs20 . \plain \f2\lang1032\fs20 \u945 \'e1\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f2\lang1032\fs20 \u927 \'cf\u7988 ?\u956 \'ec\u959 \'ef\u953 \'e9 \u8001 ? \u7944 ?\u948 \'e4\u8049 ?\u956 \'ec, \u7952 ?\u957 \'ed \u952 \'e8\u961 \'f1\u8053 ?\u957 \'ed\u8179 ? \u954 \'ea\u8051 ?\u954 \'ea\u961 \'f1\u945 \'e1\u947 \'e3\u949 \'e5\u957 \'ed \u8230 \'85 . >\u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u955 \'eb\plain \f1\lang1033\fs20 . \plain \f2\lang1032\fs20 \u946 \'e2\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f2\lang1032\fs20 \u932 \'d4\u8056 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u963 \'f3\u964 \'f4\u8049 ?\u948 \'e4\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7936 ?\u961 \'f1\u949 \'e5\u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7936 ?\u957 \'ed\u8051 ?\u969 \'f9\u954 \'ea\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs20  \u8230 \'85 . \emdash  TR, S. 100\endash 101 (D, f.\~195\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ): \plain \f1\super\lang1033\fs20 3/4\plain \f1\lang1033\fs20 >\plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u955 \'eb\plain \f1\lang1033\fs20 . \plain \f2\lang1032\fs20 \u946 \'e2\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f2\lang1032\fs20 \u7960 ?\u954 \'ea\u8049 ?\u952 \'e8\u951 \'e7\u963 \'f3\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7944 ?\u948 \'e4\u8048 ?\u956 \'ec\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7936 ?\u960 \'f0\u8051 ?\u957 \'ed\u945 \'e1\u957 \'ed\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u945 \'e1\u961 \'f1\u945 \'e1\u948 \'e4\u949 \'e5\u8055 ?\u963 \'f3\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20  \u8230 \'85 . (D, ff.\~194\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 \endash 195\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ): \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20 >\plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u960 \'f0\u955 \'eb\plain \f1\lang1033\fs20 . \plain \f2\lang1032\fs20 \u946 \'e2\u884 ?\plain \f1\lang1033\fs20 <, \plain \f1\i\lang1033\fs20 inc. \plain \f2\lang1032\fs20 \u7960 ?\u958 \'ee\u949 \'e5\u946 \'e2\u955 \'eb\u8053 ?\u952 \'e8\u951 \'e7\plain \f1\lang1033\fs20  \plain \f2\lang1032\fs20 \u7944 ?\u948 \'e4\u8048 ?\u956 \'ec\plain \f1\lang1033\fs20  \u8230 \'85 . \emdash  TR, S. 108 (D, f.\~194\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ): \plain \f1\super\lang1033\fs20 1\plain \f1\lang1033\fs20 >\plain \f2\lang1032\fs20 \u7974 ?\u967 \'f7\u959 \'ef\u962 \'f2\