\pard\fi0\li0\tx420\qj\ri0\sb240\sa0\itap0 \plain \f3\lang1033\fs24 (f. {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f3\lang1033\fs24\chcbpat17 3r}}\plain \f3\lang1033\fs24 ) Einf\u252 \'fchrung, Teil II; vgl. Cap. 1: \plain \f3\i\lang1033\fs24 2 \u8009 ? {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f3\i\lang1033\fs24\chcbpat17 \u915 G\u945 a\u955 ?\u951 ?\u957 ?\u8056 ?\u962 ?}}\plain \f3\i\lang1033\fs24  \u7952 ?\u960 p\u949 e\u8054 ? \u7952 ?\u956 \'b5\u965 ?\u8053 ?\u952 ?\u951 ? \u960 p\u949 e\u961 ?\u8054 ? \u964 t\u8182 ?\u957 ? \u964 t\u961 ?\u953 ?\u8182 ?\u957 ? \u948 d\u953 ?\u948 d\u945 a\u963 s\u954 ?\u945 a\u955 ?\u953 ?\u8182 ?\u957 ?\plain \f3\lang1033\fs24  ... . \emdash  (f. 5r, Z. 5) Einf\u252 \'fchrung, Teil III: \plain \f3\i\lang1033\fs24 3\plain \f3\lang1033\fs24  \plain \f3\i\lang1033\fs24 \u916 ?\u953 ?\u949 e\u8055 ?\u955 ?\u959 ?\u956 \'b5\u949 e\u957 ? \u964 t\u8052 ?\u957 ? \u964 t\u8049 ?\u958 ?\u953 ?\u957 ? \u964 t\u8134 ?\u962 ? \u948 d\u953 ?\u948 d\u945 a\u963 s\u954 ?\u945 a\u955 ?\u8055 ?\u945 a\u962 ? \plain \f2\i\lang1032\fs24 \u948 \'e4\u953 \'e9\u967 \'f7\plain \f1\i\lang1033\fs24 \u8182 ?\plain \f2\i\lang1032\fs24 \u962 \'f2\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\plain \f1\i\lang1033\fs24 \u8048 ? \plain \f2\i\lang1032\fs24 \u954 \'ea\u945 \'e1\u952 \'e8\plain \f1\i\lang1033\fs24 \u8057 ?\plain \f2\i\lang1032\fs24 \u955 \'eb\u959 \'ef\u957 \'ed\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u963 \'f3\u965 \'f5\u956 \'ec\u946 \'e2\u949 \'e5\u946 \'e2\u951 \'e7\u954 \'ea\plain \f1\i\lang1033\fs24 \u8057 ?\plain \f2\i\lang1032\fs24 \u964 \'f4\u945 \'e1\plain \f1\i\lang1033\fs24 . \plain \f2\i\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\i\lang1033\fs24 \u8054 ? \plain \f2\i\lang1032\fs24 \u956 \'ec\u949 \'e5\u961 \'f1\u953 \'e9\u954 \'ea\plain \f1\i\lang1033\fs24 \u8056 ?\plain \f2\i\lang1032\fs24 \u957 \'ed\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u963 \'f3\u965 \'f5\u956 \'ec\u946 \'e2\u949 \'e5\u946 \'e2\u951 \'e7\u954 \'ea\plain \f1\i\lang1033\fs24 \u8057 ?\plain \f2\i\lang1032\fs24 \u964 \'f4\u945 \'e1\plain \f1\i\lang1033\fs24  \u8003 ? \plain \f2\i\lang1032\fs24 \u954 \'ea\u945 \'e1\u952 \'e8\plain \f1\i\lang1033\fs24 \u8057 ?\plain \f2\i\lang1032\fs24 \u955 \'eb\u959 \'ef\u965 \'f5\plain \f1\i\lang1033\fs24  \u8005 ?\plain \f2\i\lang1032\fs24 \u955 \'eb\u951 \'e7\u962 \'f2\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u964 \'f4\plain \f1\i\lang1033\fs24 \u8134 ?\plain \f2\i\lang1032\fs24 \u962 \'f2\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u964 \'f4\plain \f1\i\lang1033\fs24 \u8051 ?\plain \f2\i\lang1032\fs24 \u967 \'f7\u957 \'ed\u951 \'e7\u962 \'f2\plain \f1\i\lang1033\fs24 , \u8001 ? \plain \f2\i\lang1032\fs24 \u966 \'f6\u965 \'f5\u963 \'f3\u953 \'e9\u954 \'ea\plain \f1\i\lang1033\fs24 \u8056 ?\plain \f2\i\lang1032\fs24 \u962 \'f2\plain \f1\i\lang1033\fs24  \u8003 ?\plain \f2\i\lang1032\fs24 \u962 \'f2\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u964 \'f4\u961 \'f1\u953 \'e9\u967 \'f7\plain \f1\i\lang1033\fs24 \u8182 ?\plain \f2\i\lang1032\fs24 \u962 \'f2\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\plain \f1\i\lang1033\fs24 \u8048 ? \u7944 ?\plain \f2\i\lang1032\fs24 \u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u964 \'f4\plain \f1\i\lang1033\fs24 \u8051 ?\plain \f2\i\lang1032\fs24 \u955 \'eb\u951 \'e7\u957 \'ed\plain \f3\lang1033\fs24  ... . \emdash  (f. 6ra)\plain \f1\lang1033\fs24  Cap. 1 (Verweis auf dem Professor f\u252 \'fcr Medizin Curtius [Matteo Corti [1475\endash 1542]): \plain \f2\i\lang1032\fs24 \u954 \'ea\u949 \'e5\plain \f1\i\lang1033\fs24 \u8055 ?\plain \f2\i\lang1032\fs24 \u956 \'ec\u949 \'e5\u957 \'ed\u959 \'ef\u957 \'ed\u903 ?\plain \f1\i\lang1033\fs24  Prima quidem. \plain \f2\i\lang1032\fs24 \u932 \'d4\u959 \'ef\plain \f1\i\lang1033\fs24 \u8166 ?\plain \f2\i\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u964 \'f4\plain \f1\i\lang1033\fs24 \u8048 ? \plain \f2\i\lang1032\fs24 \u960 \'f0\u961 \'f1\plain \f1\i\lang1033\fs24 \u8061 ?\plain \f2\i\lang1032\fs24 \u964 \'f4\u945 \'e1\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u954 \'ea\u945 \'e1\plain \f1\i\lang1033\fs24 \u8054 ? \plain \f2\i\lang1032\fs24 \u948 \'e4\u949 \'e5\u965 \'f5\u964 \'f4\plain \f1\i\lang1033\fs24 \u8051 ?\plain \f2\i\lang1032\fs24 \u961 \'f1\u945 \'e1\plain \f1\i\lang1033\fs24  \u7968 ?\plain \f2\i\lang1032\fs24 \u960 \'f0\plain \f1\i\lang1033\fs24 \u8049 ?\plain \f2\i\lang1032\fs24 \u964 \'f4\u951 \'e7\u963 \'f3\u949 \'e5\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u922 \'ca\u959 \'ef\u965 \'f5\u961 \'f1\u964 \'f4\u964 \'f4\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... . \emdash  (f. 10\plain \f1\super\lang1033\fs24 br\plain \f1\lang1033\fs24 ) Cap. 2: \plain \f2\i\lang1032\fs24 \u915 \'c3\u945 \'e1\u955 \'eb\u951 \'e7\u957 \'ed\u959 \'ef\plain \f1\i\lang1033\fs24 \u8166 ? \plain \f2\i\lang1032\fs24 \u948 \'e4\u949 \'e5\plain \f1\i\lang1033\fs24 \u8059 ?\plain \f2\i\lang1032\fs24 \u964 \'f4\u949 \'e5\u961 \'f1\u959 \'ef\u957 \'ed\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u954 \'ea\u949 \'e5\u966 \'f6\plain \f1\i\lang1033\fs24 \u8049 ?\plain \f2\i\lang1032\fs24 \u955 \'eb\u945 \'e1\u953 \'e9\u959 \'ef\u957 \'ed\u903 ?\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\plain \f1\i\lang1033\fs24 \u8054 ? \u8001 ?\plain \f2\i\lang1032\fs24 \u961 \'f1\u959 \'ef\plain \f1\i\lang1033\fs24 \u8166 ? \u7984 ?\plain \f2\i\lang1032\fs24 \u945 \'e1\u964 \'f4\u961 \'f1\u953 \'e9\u954 \'ea\plain \f1\i\lang1033\fs24 \u8134 ?\plain \f2\i\lang1032\fs24 \u962 \'f2\plain \f1\i\lang1033\fs24  \plain \f3\lang1033\fs24 \emdash  (f. 19ra) Zusammenfassung: \plain \f3\i\lang1033\fs24 \u7960 ?\u957 ? \u964 t\u8135 ? \u7936 ?\u957 ?\u945 a\u955 ?\u8059 ?\u963 s\u949 e\u953 ? \u964 t\u8182 ?\u957 ? \u956 \'b5\u949 e\u961 ?\u8182 ?\u957 ?\plain \f3\lang1033\fs24  \plain \f3\i\lang1033\fs24 \u964 t\u8134 ?\u962 ? \u7984 ?\u945 a\u964 t\u961 ?\u953 ?\u954 ?\u8134 ?\u962 ?\plain \f3\lang1033\fs24  ... . \emdash  (f. 22ra) Cap. 4: \plain \f3\i\lang1033\fs24 \u954 ?\u949 e\u8055 ?\u956 \'b5\u949 e\u957 ?\u959 ?\u957 ?\u903 ? Salubre simpliciter corpus bonam habet \plain \f3\lang1033\fs24 \u8230 \'85 . \emdash  (f. 28ra) Cap. 5: \plain \f3\i\lang1033\fs24 \u954 ?\u966 f. 5. Insalubre vero simpliciter\plain \f3\lang1033\fs24  <est corpus> ... . \emdash  (f. 30vb) Cap. 6: \plain \f3\i\lang1033\fs24 \u954 ?\u966 f 6. \u954 ?\u949 e\u8055 ?\u956 \'b5\u949 e\u957 ?\u959 ?\u957 ?\u903 ? Iuxta quidem primum significatum\plain \f3\lang1033\fs24  <neutrum erit corpus> ... . \emdash  (f.\~ 35v) Cap. 7: \plain \f3\i\lang1033\fs24 De signis\plain \f3\lang1033\fs24  <salubribus>, \plain \f3\i\lang1033\fs24 Cap. 7 ... \plain \f3\lang1033\fs24 . \emdash  (f. 42v) Cap. 8: \plain \f3\i\lang1033\fs24 \u7965 ?\u960 p\u949 e\u964 t\u945 a\u953 ? \u964 t\u8056 ? 8 \u954 ?\u949 e\u966 f\u8049 ?\u955 ?\u945 a\u953 ?\u959 ?\u957 ?\plain \f3\lang1033\fs24  ... . \emdash  (f. 63r) Cap. 9: \plain \f3\i\lang1033\fs24 \u954 ?\u949 e\u966 f. 9 Sunt vero. \u932 ?\u8056 ? \u954 ?\u949 e\u966 f. \u964 t\u8056 ? 9 conferratis cum cap. 83 ... \plain \f3\lang1033\fs24 . \emdash  (f. 72v) Quaestio: \plain \f3\i\lang1033\fs24 \u928 ?\u961 ?\u959 ?\u8016 ?\u964 t\u8051 ?\u952 ?\u951 ? \u950 ?\u8053 ?\u964 t\u951 ?\u956 \'b5\u945 a \u960 p\u949 e\u961 ?\u8054 ? \u7969 ?\u947 ?\u949 e\u956 \'b5\u959 ?\u957 ?\u8055 ?\u945 a\u962 ? \u964 t\u8182 ?\u957 ? \u956 \'b5\u8051 ?\u961 ?\u969 ?\u957 ?\plain \f3\lang1033\fs24  \u8230 \'85 (f. 74r) \plain \f3\i\lang1033\fs24 \u932 ?\u945 a\u8166 ?\u964 t\u945 a \u8017 ?\u960 p\u8050 ?\u961 ? \u915 G\u945 a\u955 ?\u951 ?\u957 ?\u959 ?\u8166 ?, \u964 t\u8048 ? \u948 d\u8050 ? \u7944 ?\u961 ?\u953 ?\u963 s\u964 