\pard\fi0\li0\tx420\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs24 2.  (ff. {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 4v\endash 120r}}\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 Jacobinus Bargius \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Giacomino Malafossa da Barge}}\plain \f1\lang1033\fs24 ), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Collegium}}\plain \f1\lang1033\fs24  zu {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8222 \'84Metaphysica in via Scoti}}\plain \f1\lang1033\fs24 \rdblquote , \u914 ?uch \u921 ?\u935 ? und X. Die einzelnen Abschnitte sind mit B\u945 a\u961 ?\u947 ?\u903 ?, Zitate h\u228 \'e4ufig mit \u954 ?\u949 e\u8055 ?\u956 \'b5(\u949 e\u957 ?\u959 ?\u957 ?) eingeleitet; mit \u950 ?\u8053 ?\u964 t\u951 ?\u956 \'b5\u945 a (quaestio) wird die \u252 \'fcbergreifende Diskussion einer Fragestellung bezeichnet; Kapitelangaben (\plain \f1\i\lang1033\fs24 \u954 ?\u949 e\u966 f\plain \f1\lang1033\fs24 [\u8049 ?\u955 ?\u945 a\u953 ?\u959 ?\u957 ?] oder \plain \f1\i\lang1033\fs24 test\plain \f1\lang1033\fs24 [imonium]) beziehen sich auf die damals \u252 \'fcbliche Einteilung der Metaphysik, vgl. etwa die Ausgabe Venedig 1483 ({\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 GW 2337}}\plain \f1\lang1033\fs24 ) mit den \u220 \'dcbersetzungen von {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Wilhelm von Moerbeke}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Michael Scotus}}\plain \f1\lang1033\fs24  und dem Kommentar des {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Averroes}}\plain \f1\lang1033\fs24 ; die humanistische \u220 \'dcbersetzung {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bessarions}}\plain \f1\lang1033\fs24  weicht in der Kapiteleinteilung ab, {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ioannes Argyropulos}}\plain \f1\lang1033\fs24  hat eine andere Wortwahl (beide \u220 \'dcbersetzungen in: Opus Metaphysicum, Paris 1515; s. unten Nr. 3). Als Beispiel sei Metaph. 1052b28\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (f. 96v) gegeben: Moerbeke/Michael Scotus (Text in Cod. gr. 55): gravitas et velocitas commune in contrariis\plain \f1\i\lang1033\fs24  \u8230 \'85 \plain \f1\lang1033\fs24 . \emdash  Bessarion: gravitas et celeritas ... . \emdash  Ioannes Argyropulos: pondus enim atque celeritas ... . \emdash  Die Quaestiones sind nur in Auswahl angegeben; nicht ber\u252 \'fccksichtigt sind Zitate aus anderen Aristoteles-Texten; in Klammern Seitenangabe des griechischen Textes (Kapitelanf\u228 \'e4nge).  
\par \pard\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 (ff. 4v\endash 86v) Metaph. IX (1045b27\endash 1052a11): (ff. 4v\endash 5r) \plain \f1\i\lang1033\fs24 \u924 ?\u949 e\u964 t\u945 a\u966 f\u965 ?\u963 s\u953 ?\u954 ?\u8049 ?, \u952 ?\u959 ?\u957 ? \u924 ?\u949 e\u964 t\u945 a\u966 f\u965 ?\u963 s\u953 ?\u954 ?\u8182 ?\u957 ?, \plain \f1\lang1033\fs24 inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666v/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 \u931 S\u954 ?\u959 ?\u960 p\u949 e\u8150 ?\u957 ? \u960 p\u949 e\u961 ?\u8054 ? \u8004 ?\u957 ?\u964 t\u959 ?\u962 ? \u8003 ?\u957 ? \u7952 ?\u957 ? \u7936 ?\u961 ?\u967 ?\u8135 ? \u964 t\u959 ?\u8166 ? \u946 \'df\u953 ?\u946 \'df\u955 ?\u8055 ?\u959 ?\u965 ? \u955 ?\u8051 ?\u947 ?\u949 e\u953 ?}}\plain \f1\i\lang1033\fs24 , \u8005 ?\u964 t\u953 ? \u960 p\u949 e\u961 ?\u8054 ? \u948 d\u965 ?\u957 ?\u8049 ?\u956 \'b5\u949 e\u969 ?\u962 ? \u954 ?\u945 a\u8054 ? \u7952 ?\u957 ?\u949 e\u961 ?\u947 ?\u949 e\u8055 ?\u8115 ? \u964 t\u959 ?\u8166 ? \u8004 ?\u957 ?\u964 t\u959 ?\u962 ? \u948 d\u951 ?\u955 ?\u959 ?\u8150 ? \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 \u8005 ?\u964 t\u953 ? \u964 t\u8048 ?\u962 ? \u7936 ?\u961 ?\u967 ?\u8048 ?\u962 ? \u954 ?\u945 a\u8054 ? \u964 t\u8048 ? \u945 a\u7988 ?\u964 t\u953 ?\u945 a \u952 ?\u949 e\u969 ?\u961 ?\u949 e\u8150 ? \u960 p\u961 ?\u8061 ?\u964 t\u959 ?\u965 ? \u964 t\u8055 ?\u957 ?\u959 ?\u962 ? \u8003 ? \u7936 ?\u957 ?\u8049 ?\u947 ?\u954 ?\u951 ? \u949 e\u7990 ?\u957 ?\u945 a\u953 ? \u7937 ?\u960 p\u955 ?\u8182 ?\u962 ?\plain \f1\lang1033\fs24 . \emdash  (f. 6va) \plain \f1\i\lang1033\fs24 \u916 ?\u953 ?\u945 a\u953 ?\u961 ?\u949 e\u8150 ?\u964 t\u945 a\u953 ? \u964 t\u8056 ? \u946 \'df\u953 ?\u946 \'df\u955 ?\u8055 ?\u959 ?\u957 ? \u949 e\u7984 ?\u962 ? \u946 \'df\rquote  \u956 \'b5\u8051 ?\u961 ?\u951 ?, \u964 t\u8056 ? \u960 p\u961 ?\u8182 ?\u964 t\u959 ?\u957 ? \u949 e\u7984 ?\u962 ? \u964 t\u959 ?\u8166 ? 13\plain \f1\lang1033\fs24  (= 1049b2) ... . \emdash