\pard\sl288\slmult1\fi0\li0\tx420\qj\ri0\sb120\sa0\itap0 \plain \f1\lang1033\fs24 (ff. {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1}}\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes Siglitz}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kommentar}}\plain \f1\lang1033\fs24  zu {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Galenus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De ossibus}}\plain \f1\lang1033\fs24 : I\plain \f1\i\lang1033\fs24 n Galeni libellum inscribitur \plain \f2\i\lang1032\fs24 \u928 \'d0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u8000 ?\u963 \'f3\u964 \'f4\u8182 ?\u957 \'ed\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u964 \'f4\u959 \'ef\u8150 ?\u962 \'f2\plain \f1\i\lang1033\fs24  \plain \f2\i\lang1032\fs24 \u949 \'e5\u7984 ?\u963 \'f3\u945 \'e1\u947 \'e3\u969 \'f9\u956 \'ec\u8051 ?\u957 \'ed\u959 \'ef\u953 \'e9\u962 \'f2\plain \f1\i\lang1033\fs24  De ossibus ad medicinae tyrones erudientos (!). Proposita \u224 \'e0 praestantissimo et experientissimo domino d. Joanne Siglicio Medicinae Doctore et Professore huius Academiae publi. diebus canicularibus A. 1616. \emdash  \plain \f2\i\lang1032\fs24 \u8025 ?\u960 \'f0\u959 \'ef\u956 \'ec\u957 \'ed\u8053 ?\u956 \'ec\u945 \'e1\u964 \'f4\u945 \'e1\plain \f1\i\lang1033\fs24 , inc. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Disciplinae anatomicaeque particulae Medicinae Physiologicae totidem corporis humanis partium generibus}}\plain \f1\i\lang1033\fs24  \u8230 \'85 des. lib. de motu musculorum.\plain \f1\lang1033\fs24  Darunter: \plain \f1\i\lang1033\fs24 Finis.\plain \f1\lang1033\fs24  \emdash  (ff. 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Leer.}

