antius\plain \f1\lang1033\fs20\cf1  (Anthologia Graeca IX, 385): >\u7964 ?<\plain \f2\lang1032\fs20\cf1 \u956 \'ec\u956 \'ec\u949 \'e5\u964 \'f4\u961 \'f1\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7952 ?\u960 \'f0\u953 \'e9\u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u8053 ?\u903 ?\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7948 ?\u955 \'eb\u966 \'f6\u945 \'e1\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u955 \'eb\u953 \'e9\u964 \'f4\u8048 ?\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u935 \'d7\u961 \'f1\u8059 ?\u963 \'f3\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20\cf1 , \plain \f2\lang1032\fs20\cf1 \u955 \'eb\u959 \'ef\u953 \'e9\u956 \'ec\u8056 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u963 \'f3\u964 \'f4\u961 \'f1\u945 \'e1\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs20\cf1 , \plain \f2\lang1032\fs20\cf1 \u7956 ?\u967 \'f7\u952 \'e8\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7936 ?\u957 \'ed\u940 \'dc\u954 \'ea\u964 \'f4\u969 \'f9\plain \f1\lang1033\fs20\cf1 .}

