\pard\fi0\li0\tx345\tx675\qj\ri0\sb75\sa0\itap0 \plain \f1\lang1033\fs20\cf1 6.\tab (ff. 3\plain \f1\super\lang1033\fs20\cf1 r\plain \f1\lang1033\fs20\cf1 \endash 31\plain \f1\super\lang1033\fs20\cf1 r\plain \f1\lang1033\fs20\cf1 ) \plain \f1\b\lang1033\fs20\cf1 Ioannes Tzetzes\plain \f1\lang1033\fs20\cf1 , Exegesis in Homeri Iliadem, ed. H\plain \f1\scaps\lang1033\fs20\cf1 ermann \plain \f1\lang1033\fs20\cf1 1832 (\plain \f1\i\lang1033\fs20\cf1 Lit\plain \f1\lang1033\fs20\cf1 ), Teil II, S. 3\endash 125 (aus Cod. gr. 32, zur Hs. vgl. S. V\endash VIII); B\plain \f1\scaps\lang1033\fs20\cf1 achmann 1835 \plain \f1\lang1033\fs20\cf1 (\plain \f1\i\lang1033\fs20\cf1 Lit\plain \f1\lang1033\fs20\cf1 )\plain \f1\scaps\lang1033\fs20\cf1 , S. 746\plain \f1\scaps\lang1033\fs20\cf1 \endash \plain \f1\scaps\lang1033\fs20\cf1 824 (\plain \f1\lang1033\fs20\cf1 aus Cod. gr. 32); \plain \f1\scaps\lang1033\fs20\cf1 Papathomopulos\plain \f1\lang1033\fs20\cf1  2007 (\plain \f1\i\lang1033\fs20\cf1 Lit\plain \f1\lang1033\fs20\cf1 ;\plain \f1\i\lang1033\fs20\cf1  \plain \f1\lang1033\fs20\cf1 u. a. aus Cod. gr. 32, zur Hs. vgl. S.\~7*), S. 3\endash 193: Titel: >\plain \f2\lang1032\fs20\cf1 \u917 \'c5\plain \f1\lang1033\fs20\cf1 <\plain \f2\lang1032\fs20\cf1 \u7984 ?\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u8009 ?\u956 \'ec\u8053 ?\u961 \'f1\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7992 ?\u955 \'eb\u953 \'e9\u940 \'dc\u948 \'e4\u945 \'e1\plain \f1\lang1033\fs20\cf1 , \plain \f2\lang1032\fs20\cf1 \u7952 ?\u958 \'ee\u8053 ?\u947 \'e3\u951 \'e7\u963 \'f3\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7992 ?\u969 \'f9\u940 \'dc\u957 \'ed\u957 \'ed\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u915 \'c3\u961 \'f1\u945 \'e1\u956 \'ec\u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\u954 \'ea\u959 \'ef\u8166 ?\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u932 \'d4\u950 \'e6\u8051 ?\u964 \'f4\u950 \'e6\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20\cf1 <. \emdash  Metrische Einleitung: \plain \f2\lang1032\fs20\cf1 \u914 \'c2\u8055 ?\u946 \'e2\u955 \'eb\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7953 ?\u945 \'e1\u8150 ?\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u960 \'f0\u961 \'f1\u945 \'e1\u960 \'f0\u8055 ?\plain \f1\lang1033\fs20\cf1 \-\plain \f2\lang1032\fs20\cf1 \u948 \'e4\u949 \'e5\u963 \'f3\u963 \'f3\u953 \'e9\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u947 \'e3\u955 \'eb\u945 \'e1\u966 \'f6\u965 \'f5\u961 \'f1\u959 \'ef\u955 \'eb\u8059 ?\u964 \'f4\u949 \'e5\u953 \'e9\u961 \'f1\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u8009 ?\u956 \'ec\u8053 ?\u961 \'f1\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs20\cf1  | \plain \f2\lang1032\fs20\cf1 \u964 \'f4\u8053 ?\u957 \'ed\u948 \'e4\u949 \'e5\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u960 \'f0\u945 \'e1\u961 \'f1\u945 \'e1\u953 \'e9\u966 \'f6\u945 \'e1\u963 \'f3\u8055 ?\u8131 ?\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7952 ?\u956 \'ec\u8182 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7953 ?\u964 \'f4\u940 \'dc\u961 \'f1\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u964 \'f4\u959 \'ef\u955 \'eb\u965 \'f5\u960 \'f0\u949 \'e5\u8059 ?\u963 \'f3\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs20\cf1  | \plain \f2\lang1032\fs20\cf1 \u960 \'f0\u945 \'e1\u953 \'e9\u963 \'f3\u8054 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u8009 ?\u956 \'ec\u951 \'e7\u961 \'f1\u953 \'e9\u940 \'dc\plain \f1\lang1033\fs20\cf1 \-\plain \f2\lang1032\fs20\cf1 \u948 \'e4\u945 \'e1\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7953 ?\u961 \'f1\u956 \'ec\u8053 ?\u970 \'fa\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u8036 ?\u960 \'f0\u945 \'e1\u963 \'f3\u945 \'e1\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u948 \'e4\u8182 ?\u961 \'f1\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs20\cf1  | \plain \f2\lang1032\fs20\cf1 \u947 \'e3\u961 \'f1\u945 \'e1\u956 \'ec\u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\u954 \'ea\u8056 ?\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u960 \'f0\u949 \'e5\u961 \'f1\u8055 ?\u945 \'e1\u955 \'eb\u955 \'eb\u945 \'e1\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u956 \'ec\u959 \'ef\u947 \'e3\u8053 ?\u963 \'f3\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7992 ?\u969 \'f9\u940 \'dc\u957 \'ed\u957 \'ed\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs20\cf1  | \plain \f2\lang1032\fs20\cf1 \u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u932 \'d4\u950 \'e6\u8051 ?\u964 \'f4\u950 \'e6\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u954 \'ea\u945 \'e1\u955 \'eb\u8051 ?\u959 \'ef\u965 \'f5\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7952 ?\u960 \'f0\u969 \'f9\u957 \'ed\u965 \'f5\u956 \'ec\u8055 ?\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7952 ?\u961 \'f1\u8051 ?\u959 \'ef\u957 \'ed\u964 \'f4\u949 \'e5\u962 \'f2\plain \f1\lang1033\fs20\cf1 . \emdash  Text: \plain \f1\i\lang1033\fs20\cf1 inc. \plain \f1\lang1033\fs20\cf1 >\plain \f2\lang1032\fs20\cf1 \u928 \'d0\plain \f1\lang1033\fs20\cf1 <\plain \f2\lang1032\fs20\cf1 \u959 \'ef\u955 \'eb\u955 \'eb\u959 \'ef\u8054 ?\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u956 \'ec\u8050 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7936 ?\u961 \'f1\u967 \'f7\u945 \'e1\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u8001 ?\u956 \'ec\u951 \'e7\u961 \'f1\u953 \'e9\u954 \'ea\u8052 ?\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7952 ?\u960 \'f0\u953 \'e9\u954 \'ea\u949 \'e5\plain \f1\lang1033\fs20\cf1 \-\plain \f2\lang1032\fs20\cf1 \u967 \'f7\u949 \'e5\u953 \'e9\u961 \'f1\u8053 ?\plain \f1\lang1033\fs20\cf1 \-\plain \f2\lang1032\fs20\cf1 \u954 \'ea\u949 \'e5\u963 \'f3\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7992 ?\u955 \'eb\u953 \'e9\u8049 ?\u948 \'e4\u945 \'e1\plain \f1\lang1033\fs20\cf1  \plain \f2\lang1032\fs20\cf1 \u7952 ?\u960 \'f0\u949 \'e5\u958 \'ee\u949 \'e5\u961 \'f1\u947 \'e3\u8049 ?\u963 \'f3\u945 \'e1\u963 \'f3\u952 \'e8\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs20\cf1  ... \plain \f1\i\lang1033\fs20\cf1 des.\plain \f1\lang1033\fs20\cf1  (A\plain \f2\lang1032\fs20\cf1 102) \u959 \'ef\u7985 ? \u947 \'e3\u8048 ?\u961 \'f1 \u7940 ?\u955 \'eb\u955 \'eb\u959 \'ef\u953 \'e9 \u956 \'ec\u949 \'e5\u961 \'f1\u953 \'e9\u954 \'ea\u8182 ?\u962 \'f2 \u7952 ?\u954 \'ea\u961 \'f1\u940 \'dc\u964 \'f4\u959 \'ef\u965 \'f5\u957 \'ed \u964 \'f4\u959 \'ef\u960 \'f0\u945 \'e1\u961 \'f1\u967 \'f7\u959 \'ef\u8166 ?\u957 \'ed\u964 \'f4\u949 \'e5\u962 \'f2. \emdash  (\plain \f1\lang1033\fs20\cf1 ff. 31\plain \f1\super\lang1033\fs20\cf1 v\plain \f1\lang1033\fs20\cf1 \endash 32\plain \f1\super\lang1033\fs20\cf1 v\plain \f1\lang1033\fs20\cf1 ) Leer.
\par \pard\fi0\li0\tx225\tx450\qj\ri0\sb60\sa120\itap0 \plain \f3\lang1033\fs20 (ff. 3\plain \f3\super\lang1033\fs20 r\plain \f3\lang1033\fs20 \endash 21\plain \f3\super\lang1033\fs20 r\plain \f3\lang1033\fs20 , in margine) Scholia in Ioannem Tzetzem, ed. H\plain \f3\scaps\lang1033\fs20 ermann \plain \f3\lang1033\fs20 1832 (\plain \f3\i\lang1033\fs20 Lit\plain \f3\lang1033\fs20 ), S. 125\endash 156; \plain \f3\scaps\lang1033\fs20 Bachmann 1835 \plain \f3\lang1033\fs20 (\plain \f3\i\lang1033\fs20 Lit\plain \f3\lang1033\fs20 )\plain \f3\scaps\lang1033\fs20 , S. 825\plain \f3\scaps\lang1033\fs20 \endash \plain \f3\scaps\lang1033\fs20 845; Papathomopulos\plain \f3\lang1033\fs20  2007 (\plain \f3\i\lang1033\fs20 Lit\plain \f3\lang1033\fs20 ), S. 417\endash 460\plain \f3\scaps\lang1033\fs20 : \plain \f3\i\lang1033\fs20 inc.\plain \f3\lang1033\fs20  (zu \plain \f3\scaps\lang1033\fs20 Hermann, \plain \f3\lang1033\fs20 S. 3,\~10; \plain \f3\scaps\lang1033\fs20 Bachmann\plain \f3\lang1033\fs20 , S. 746,\~9): \plain \f2\lang1032\fs20 \u8041 ?\u962 \'f2\plain \f3\lang1033\fs20  \u8001 ? \plain \f2\lang1032\fs20 \u7944 ?\u961 \'f1\u8055 ?\u963 \'f3\u964 \'f4\u945 \'e1\u961 \'f1\u967 \'f7\u959 \'ef\u962 \'f2\plain \f3\lang1033\fs20  \plain \f2\lang1032\fs20 \u954 \'ea\u945 \'e1\u8054 ?\plain \f3\lang1033\fs20  \plain \f2\lang1032\fs20 \u959 \'ef\u7985 ?\plain \f3\lang1033\fs20  \plain \f2\lang1032\fs20 \u963 \'f3\u8058 ?\u957 \'ed\plain \f3\lang1033\fs20  \plain \f2\lang1032\fs20 \u945 \'e1\u8016 ?\u964 \'f4\u8183 ?\u903 ?\plain \f3\lang1033\fs20  \plain \f2\lang1032\fs20 \u7953 ?\u946 \'e2\u948 \'e4\u959 \'ef\u956 \'ec\u8053 ?\u954 \'ea\u959 \'ef\u957 \'ed\u964 \'f4\u945 \'e1\plain \f3\lang1033\fs20  \plain \f2\lang1032\fs20 \u954 \'ea\u945 \'e1\u8054 ?\plain \f3\lang1033\fs20  \plain \f2\lang1032\fs20 \u948 \'e4\u8059 ?\u959 \'ef\plain \f3\lang1033\fs20  \plain \f2\lang1032\fs20 \u947 \'e3\u961 \'f1\u945 \'e1\u956 \'ec\u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\u954 \'ea\u959 \'ef