\pard\sl288\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f4\lang1033\fs24 3.\tab (f. 338\plain \f4\super\lang1033\fs24 v\plain \f4\lang1033\fs24 ) \plain \f4\b\lang1033\fs24 Anthologia Graeca\plain \f4\lang1033\fs24 , \plain \f2\lang1032\fs24 \u921 \'c9\u935 \'d7\plain \f4\lang1033\fs24 , 359; mit Angabe von L\u228 \'e4ngen und K\u252 \'fcrzen \u252 \'fcber dem Text: >\plain \f2\lang1032\fs24 \u931 \'d3\u949 \'e5\u955 \'eb\u8051 ?\u957 \'ed\u964 \'f4\u953 \'e9\u945 \'e1\plain \f4\lang1033\fs24  \u7970 ? \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u951 \'e7\u967 \'f7\u951 \'e7\u964 \'f4\u953 \'e9\u954 \'ea\u959 \'ef\u8054 ?\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u953 \'e9\plain \f4\lang1033\fs24 . \plain \f2\lang1032\fs24 \u7936 ?\u948 \'e4\u8051 ?\u963 \'f3\u960 \'f0\u959 \'ef\u964 \'f4\u959 \'ef\u953 \'e9\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u959 \'ef\u7985 ?\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8050 ?\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u7944 ?\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u964 \'f4\u8051 ?\u955 \'eb\u959 \'ef\u965 \'f5\u962 \'f2\plain \f4\lang1033\fs24 , \plain \f4\i\lang1033\fs24 inc. \plain \f4\lang1033\fs24 >\plain \f2\lang1032\fs24 \u928 \'d0\plain \f4\lang1033\fs24 <\plain \f2\lang1032\fs24 \u959 \'ef\u8055 ?\u951 \'e7\u957 \'ed\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\u962 \'f2\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u953 \'e9\u8057 ?\u964 \'f4\u959 \'ef\u953 \'e9\u959 \'ef\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u940 \'dc\u956 \'ec\u959 \'ef\u953 \'e9\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u961 \'f1\u8055 ?\u946 \'e2\u969 \'f9\u957 \'ed\plain \f4\lang1033\fs24  ... \plain \f4\i\lang1033\fs24 des. \plain \f2\lang1032\fs24 \u956 \'ec\u951 \'e7\u948 \'e4\u8051 ?\plain \f4\lang1033\fs24 \-\plain \f2\lang1032\fs24 \u960 \'f0\u959 \'ef\u964 \'f4\plain \f4\lang1033\fs24 \rquote  \u7970 ? \plain \f2\lang1032\fs24 \u8127 ?\u960 \'f0\u959 \'ef\u952 \'e8\u945 \'e1\u957 \'ed\u949 \'e5\u8150 ?\u957 \'ed\plain \f4\lang1033\fs24 . \plain \f2\lang1032\fs24 \u964 \'f4\plain \f4\lang1033\fs24 \rquote  \plain \f2\lang1032\fs24 \u7940 ?\u955 \'eb\u955 \'eb\u945 \'e1\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u948 \'e4\u8050 ?\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u940 \'dc\u957 \'ed\u964 \'f4\u945 \'e1\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u8051 ?\u955 \'eb\u969 \'f9\u962 \'f2\plain \f4\lang1033\fs24 . \emdash  (f.\~338\plain \f4\super\lang1033\fs24 v\plain \f4\lang1033\fs24 ) \plain \f4\b\lang1033\fs24 Anthologia Graeca\plain \f4\lang1033\fs24 , \plain \f2\lang1032\fs24 \u921 \'c9\u935 \'d7\plain \f4\lang1033\fs24 , 360\plain \f4\scaps\lang1033\fs24 : \plain \f4\scaps\lang1033\fs24 \u7960 ?\plain \f2\lang1032\fs24 \u954 \'ea\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\u945 \'e1\u957 \'ed\u964 \'f4\u8055 ?\u959 \'ef\u965 \'f5\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u960 \'f0\u953 \'e9\u952 \'e8\u945 \'e1\u957 \'ed\u959 \'ef\u8055 ?\plain \f4\lang1033\fs24 . \plain \f2\lang1032\fs24 \u924 \'cc\u951 \'e7\u964 \'f4\u961 \'f1\u959 \'ef\u948 \'e4\u974 \'fe\u961 \'f1\u959 \'ef\u965 \'f5\plain \f4\lang1033\fs24 , \plain \f4\i\lang1033\fs24 inc. \plain \f4\lang1033\fs24 >\plain \f2\lang1032\fs24 \u928 \'d0\plain \f4\lang1033\fs24 <\plain \f2\lang1032\fs24 \u945 \'e1\u957 \'ed\u964 \'f4\u959 \'ef\u8055 ?\u951 \'e7\u957 \'ed\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u953 \'e9\u8057 ?\plain \f4\lang1033\fs24 \-\plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u953 \'e9\u959 \'ef\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u940 \'dc\u956 \'ec\u959 \'ef\u953 \'e9\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u964 \'f4\u961 \'f1\u8055 ?\u946 \'e2\u959 \'ef\u957 \'ed\plain \f4\lang1033\fs24  ... \plain \f4\i\lang1033\fs24 des. \plain \f2\lang1032\fs24 \u956 \'ec\u951 \'e7\u948 \'e4\u8051 ?\u960 \'f0\u959 \'ef\u964 \'f4\u949 \'e5\plain \f4\lang1033\fs24  \u7970 ? \plain \f2\lang1032\fs24 \u8127 ?\u960 \'f0\u959 \'ef\u952 \'e8\u945 \'e1\u957 \'ed\u949 \'e5\u8150 ?\u957 \'ed\plain \f4\lang1033\fs24 \u8729 \'b7 \plain \f2\lang1032\fs24 \u960 \'f0\u940 \'dc\u957 \'ed\u964 \'f4\u945 \'e1\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u947 \'e3\u8048 ?\u961 \'f1\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u7952 ?\u963 \'f3\u952 \'e8\u955 \'eb\u8048 ?\plain \f4\lang1033\fs24  \plain \f2\lang1032\fs24 \u946 \'e2\u8055 ?\u8179 ?\plain \f4\lang1033\fs24 . \emdash  (f. 339\plain \f4\super\lang1033\fs24 rv\plain \f4\lang1033\fs24 ) Siehe oben vor f. 269.}

